type RichInlineImageCellPointBookmark = {
  nodePath: number[];
  nodeOffset: number;
  textOffset: number;
};

type RichInlineImageInsertionBookmark =
  | {
      scope: "editor";
      selection: RichEditorSelectionBookmark;
    }
  | {
      scope: "table-cell";
      tableIndex: number;
      rowIndex: number;
      cellIndex: number;
      start: RichInlineImageCellPointBookmark;
      end: RichInlineImageCellPointBookmark;
    };

function stripPendingStyleCaretMarkersFromHtml(html: string) {
  return html.replace(/\u200B/g, "");
}

function cleanEditorHtmlForRichTextSession(html: string) {
  const withoutCaretMarkers = sanitizeRichTextHtml(
    stripPendingStyleCaretMarkersFromHtml(html || "<p></p>")
  );
  if (!withoutCaretMarkers.includes("paideia-rich-table-cell-selected") &&
      !withoutCaretMarkers.includes("data-paideia-table-editor-only")) {
    return withoutCaretMarkers;
  }
  const template = document.createElement("template");
  template.innerHTML = withoutCaretMarkers;
  template.content.querySelectorAll(".paideia-rich-table-cell-selected").forEach((cell) => {
    cell.classList.remove("paideia-rich-table-cell-selected");
  });
  template.content.querySelectorAll("[data-paideia-table-editor-only]").forEach((node) => node.remove());
  return template.innerHTML || "<p></p>";
}

function normalizeEmptyRichTextListItems(root: HTMLElement) {
  const isEmptyListItem = (item: HTMLLIElement) =>
    !item.textContent?.replace(/[\u200B\u00A0]/g, "").trim() &&
    !item.querySelector("img, video, audio, iframe, svg, canvas, table, hr, input");

  // Les listes imbriquees sont normalisees d'abord pour ne jamais invalider
  // le parcours de leur liste parente.
  const lists = Array.from(root.querySelectorAll<HTMLUListElement | HTMLOListElement>("ul, ol")).reverse();
  lists.forEach((list) => {
    const items = Array.from(list.children).filter(
      (child): child is HTMLLIElement => child instanceof HTMLLIElement,
    );
    if (!items.some(isEmptyListItem)) {
      return;
    }

    const replacement = document.createDocumentFragment();
    const initialOrdinal = list instanceof HTMLOListElement ? list.start || 1 : 1;
    let nextOrdinal = initialOrdinal;
    let currentChunk: HTMLUListElement | HTMLOListElement | null = null;
    let followsBlankLine = false;

    items.forEach((item) => {
      if (isEmptyListItem(item)) {
        if (currentChunk) {
          currentChunk.style.marginBlockEnd = "0px";
        }
        currentChunk = null;
        const blankLine = document.createElement("div");
        blankLine.style.marginBlock = "0px";
        blankLine.append(document.createElement("br"));
        replacement.append(blankLine);
        followsBlankLine = true;
        return;
      }

      if (!currentChunk) {
        currentChunk = list.cloneNode(false) as HTMLUListElement | HTMLOListElement;
        if (followsBlankLine) {
          currentChunk.style.marginBlockStart = "0px";
        }
        if (currentChunk instanceof HTMLOListElement) {
          currentChunk.start = nextOrdinal;
        }
        replacement.append(currentChunk);
      }
      currentChunk.append(item);
      nextOrdinal += 1;
      followsBlankLine = false;
    });

    list.replaceWith(replacement);
  });
}


function formatCount(count: number, singular: string, plural: string) {
  return `${count} ${count > 1 ? plural : singular}`;
}

async function scormBatchArchivePath(destinationRoot: string, title: string, usedNames: Set<string>) {
  const stem = scormArchiveFileName(title).replace(/\.zip$/i, "");
  let candidate = `${stem}.zip`;
  let counter = 2;
  const normalizedRoot = destinationRoot.replace(/\\/g, "/").replace(/\/+$/g, "");
  while (usedNames.has(candidate.toLowerCase()) || await pathExists(`${normalizedRoot}/${candidate}`)) {
    candidate = `${stem}_${counter}.zip`;
    counter += 1;
  }
  usedNames.add(candidate.toLowerCase());
  return `${normalizedRoot}/${candidate}`;
}

function parentPath(path: string) {
  const normalized = path.replace(/\\/g, "/");
  const index = normalized.lastIndexOf("/");
  return index >= 0 ? normalized.slice(0, index) : "";
}

function timestampForArchiveName() {
  const now = new Date();
  const pad = (value: number) => String(value).padStart(2, "0");
  return `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}_${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
}

