async function createCroppedImageFile(
  src: string,
  sourceName: string,
  crop: ImageCrop,
  options: { containInSquare?: boolean } = {}
) {
  const normalized = normalizeImageCrop(crop);
  if (!normalized) {
    return null;
  }

  const sourceBlob = await fetch(src).then((response) => {
    if (!response.ok) {
      throw new Error("Impossible de lire l'image a cropper.");
    }
    return response.blob();
  });
  const objectUrl = URL.createObjectURL(sourceBlob);
  const image = await new Promise<HTMLImageElement>((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error("Impossible de charger l'image a cropper."));
    img.src = objectUrl;
  });

  try {
    const sourceWidth = image.naturalWidth || image.width;
    const sourceHeight = image.naturalHeight || image.height;
    const sx = Math.round((normalized.x / 100) * sourceWidth);
    const sy = Math.round((normalized.y / 100) * sourceHeight);
    const sw = Math.max(1, Math.round((normalized.width / 100) * sourceWidth));
    const sh = Math.max(1, Math.round((normalized.height / 100) * sourceHeight));
    const placement = resolveCropOutputPlacement(sw, sh, Boolean(options.containInSquare));
    const canvas = document.createElement("canvas");
    canvas.width = placement.canvasWidth;
    canvas.height = placement.canvasHeight;
    const context = canvas.getContext("2d");
    if (!context) {
      return null;
    }

    if (normalized.shape === "ellipse") {
      context.save();
      context.beginPath();
      context.ellipse(
        placement.drawX + sw / 2,
        placement.drawY + sh / 2,
        sw / 2,
        sh / 2,
        0,
        0,
        Math.PI * 2
      );
      context.clip();
    }
    context.drawImage(image, sx, sy, sw, sh, placement.drawX, placement.drawY, sw, sh);
    if (normalized.shape === "ellipse") {
      context.restore();
    }
    const requiresTransparentCanvas = normalized.shape === "ellipse" || Boolean(options.containInSquare);
    const fileName = requiresTransparentCanvas
      ? ellipticalCroppedImageFileName(sourceName)
      : croppedImageFileName(sourceName);
    const mimeType = requiresTransparentCanvas ? "image/png" : imageMimeTypeFromName(fileName);
    const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, mimeType, 0.92));
    if (!blob) {
      return null;
    }

    return new File([blob], fileName, { type: mimeType });
  } finally {
    URL.revokeObjectURL(objectUrl);
  }
}

function isWhiteColorValue(value?: string | null) {
  const normalized = value?.trim().toLocaleLowerCase("fr-FR");
  return normalized === "#fff" || normalized === "#ffffff" || normalized === "white" || normalized === "rgb(255, 255, 255)";
}

function isSoftAudioBorderColorValue(value?: string | null) {
  const normalized = value?.trim().toLocaleLowerCase("fr-FR").replace(/\s+/g, "");
  return normalized === "#d5dae3" || normalized === "rgba(18,58,122,.16)" || normalized === "rgba(18,58,122,0.16)";
}

function audioAccentColor(block: Pick<PaideiaBlock, "buttonTextColor" | "panelBorderColor">) {
  const buttonTextColor = block.buttonTextColor?.trim();
  if (buttonTextColor && !isWhiteColorValue(buttonTextColor)) {
    return buttonTextColor;
  }
  const panelBorderColor = block.panelBorderColor?.trim();
  if (panelBorderColor && !isSoftAudioBorderColorValue(panelBorderColor)) {
    return panelBorderColor;
  }
  return "#748CB4";
}

function isEditableShortcutTarget(target: EventTarget | null) {
  return (
    target instanceof HTMLElement &&
    (target.isContentEditable || Boolean(target.closest("input, textarea, select, [contenteditable='true']")))
  );
}

function isAssistantShortcut(event: KeyboardEvent) {
  return (
    event.shiftKey &&
    !event.ctrlKey &&
    !event.altKey &&
    (event.key === "<" || event.key === ">" || event.code === "IntlBackslash" || event.code === "Backquote")
  );
}

async function dataUrlToBytes(dataUrl: string) {
  const response = await fetch(dataUrl);
  return new Uint8Array(await response.arrayBuffer());
}

const BUNDLED_LESSON_FONTS = [
  { id: "inter", family: "Inter", folder: "Inter", regular: "Inter-Regular.woff2" },
  { id: "be-vietnam-pro", family: "Be Vietnam Pro", folder: "Be_Vietnam_Pro", regular: "BeVietnamPro-Regular.woff2" },
  { id: "atkinson-hyperlegible", family: "Atkinson Hyperlegible", folder: "Atkinson_Hyperlegible", regular: "AtkinsonHyperlegible-Regular.woff2" },
  { id: "roboto", family: "Roboto", folder: "Roboto", regular: "Roboto-Regular.woff2" },
  { id: "open-dyslexic", family: "OpenDyslexic", folder: "opendyslexic-0.92", regular: "OpenDyslexic-Regular.woff2" },
  { id: "lexend", family: "Lexend", folder: "Lexend", regular: "Lexend-Regular.woff2" },
  { id: "liberation-sans", family: "Liberation Sans", folder: "Liberation_Sans", regular: "LiberationSans-Regular.woff2" }
] as const;

function bundledLessonFontFaceCss() {
  const lessonFaces = BUNDLED_LESSON_FONTS.map(
    (font) =>
      `@font-face{font-family:"PaideiaPreview-${font.id}";src:url("/fonts/${font.folder}/${font.regular}") format("${font.regular.endsWith(".woff2") ? "woff2" : "woff"}");font-weight:400;font-style:normal;font-display:swap;}`
  );
  return [
    ...lessonFaces,
    '@font-face{font-family:"PaideiaQuoteMarkFont";src:url("/fonts/Bellefair/Bellefair-Regular.woff2") format("woff2");font-weight:400;font-style:normal;font-display:swap;}',
    '@font-face{font-family:"PaideiaQuoteFont";src:url("/fonts/Spectral/Spectral-Regular.woff2") format("woff2");font-weight:400;font-style:normal;font-display:swap;}',
    '@font-face{font-family:"PaideiaQuoteFont";src:url("/fonts/Spectral/Spectral-Italic.woff2") format("woff2");font-weight:400;font-style:italic;font-display:swap;}',
    '@font-face{font-family:"PaideiaQuoteFont";src:url("/fonts/Spectral/Spectral-Bold.woff2") format("woff2");font-weight:700;font-style:normal;font-display:swap;}',
    '@font-face{font-family:"PaideiaQuoteFont";src:url("/fonts/Spectral/Spectral-BoldItalic.woff2") format("woff2");font-weight:700;font-style:italic;font-display:swap;}'
  ].join("\n");
}

function fontCssFormat(assetRef: string) {
  const extension = assetRef.split(".").pop()?.toLowerCase();
  return extension === "woff2" ? "woff2" : extension === "woff" ? "woff" : extension === "otf" ? "opentype" : "truetype";
}

function userFontCatalogFaceCss(fonts: LessonCustomFont[]) {
  return fonts.flatMap((font) =>
    (font.faces?.length ? font.faces : []).map((face) => {
      const url = isTauri() ? convertFileSrc(face.assetRef) : `/@fs/${encodeFsPath(face.assetRef)}`;
      return `@font-face{font-family:"PaideiaUser-${font.id}";src:url("${url}") format("${fontCssFormat(face.assetRef)}");font-weight:${face.weight};font-style:${face.style};font-display:swap;}`;
    })
  ).join("\n");
}

function richTextFontCssFamily(fontId: string) {
  return `PaideiaRichFont-${fontId}`;
}

function projectRichTextFontFaceCss(projectPath: string, fonts: LessonCustomFont[]) {
  return fonts.flatMap((font) => {
    const faces = font.faces?.length
      ? font.faces
      : [{ assetRef: font.assetRef, weight: 400, style: "normal" as const }];
    const family = richTextFontCssFamily(font.id ?? "");
    return faces.map((face) => {
      const fontUrl = buildAssetUrl(projectPath, face.assetRef);
      const format = fontCssFormat(face.assetRef);
      return fontUrl
        ? `@font-face{font-family:"${family}";src:url("${fontUrl}") format("${format}");font-weight:${face.weight};font-style:${face.style};font-display:swap;}`
        : "";
    });
  }).filter(Boolean).join("\n");
}

function customLessonFontFaceCss(projectPath: string, project?: PaideiaProject | null) {
  const font = project?.customFont;
  if (!font?.assetRef) {
    return "";
  }
  const faces = font.faces?.length
    ? font.faces
    : [{ assetRef: font.assetRef, weight: 400, style: "normal" as const }];
  return faces
    .map((face) => {
      const fontUrl = buildAssetUrl(projectPath, face.assetRef);
      const format = fontCssFormat(face.assetRef);
      return fontUrl
        ? `@font-face{font-family:"PaideiaCustomFont";src:url("${fontUrl}") format("${format}");font-weight:${face.weight};font-style:${face.style};font-display:swap;}`
        : "";
    })
    .filter(Boolean)
    .join("\n");
}

function lessonSessionCustomFontFamily(projectPath: string, project?: PaideiaProject | null) {
  const scope = (project?.id || projectPath || "project").replace(/[^A-Za-z0-9_-]/g, "-");
  return `PaideiaSessionCustomFont-${scope}`;
}

function lessonSessionCustomFontFaceCss(projectPath: string, project?: PaideiaProject | null) {
  return customLessonFontFaceCss(projectPath, project).replace(
    /font-family:"PaideiaCustomFont"/g,
    `font-family:"${lessonSessionCustomFontFamily(projectPath, project)}"`
  );
}

function customLessonFontStyle(
  projectPath: string,
  project?: PaideiaProject | null,
  activitySpacingOverride?: number | null
): CSSProperties | undefined {
  const activitySpacingPx = clampLessonActivitySpacing(activitySpacingOverride ?? project?.activitySpacingPx);
  const courseAppearance = normalizeCourseAppearance(project?.courseAppearance);
  return {
    "--lesson-activity-spacing": `${activitySpacingPx}px`,
    "--content-text": resolvedCourseTextColor(courseAppearance),
    "--lesson-background": courseAppearance.backgroundColor,
    "--lesson-custom-font": project?.customFont?.assetRef
      ? `"${lessonSessionCustomFontFamily(projectPath, project)}", "PaideiaPreview-inter", Inter, Arial, sans-serif`
      : '"PaideiaPreview-inter", Inter, Arial, sans-serif'
  } as CSSProperties;
}

const DEFAULT_LESSON_ACTIVITY_SPACING = 30;
const MIN_LESSON_ACTIVITY_SPACING = 15;
const MAX_LESSON_ACTIVITY_SPACING = 60;
const MAX_BLOCK_PADDING_OFFSET = 90;

function clampLessonActivitySpacing(value?: number | null): number {
  if (!Number.isFinite(value)) {
    return DEFAULT_LESSON_ACTIVITY_SPACING;
  }

  return Math.max(MIN_LESSON_ACTIVITY_SPACING, Math.min(MAX_LESSON_ACTIVITY_SPACING, Math.round(Number(value))));
}

function clampBlockPaddingOffset(
  value: number | null | undefined,
  basePadding: number,
  minimumPadding = 0,
  maximumPadding: number | null = null
): number {
  const minimumOffset = minimumPadding - basePadding;
  const maximumOffset = maximumPadding == null
    ? MAX_BLOCK_PADDING_OFFSET
    : Math.max(minimumOffset, Math.min(MAX_BLOCK_PADDING_OFFSET, maximumPadding - basePadding));
  const normalizedValue = Number.isFinite(value) ? Math.round(Number(value)) : 0;

  return Math.max(minimumOffset, Math.min(maximumOffset, normalizedValue));
}

function projectRichTextFontFamilies(projectPath: string, project: PaideiaProject | null, fonts: LessonCustomFont[]) {
  const families = new Set<string>();
  if (project?.customFont?.assetRef) {
    families.add(lessonSessionCustomFontFamily(projectPath, project));
  } else {
    families.add("PaideiaPreview-inter");
  }
  fonts.forEach((font) => {
    if (font.id) families.add(richTextFontCssFamily(font.id));
  });
  const serializedProject = project ? JSON.stringify(project) : "";
  for (const match of serializedProject.matchAll(/PaideiaRichFont-[A-Za-z0-9_-]+/g)) {
    families.add(match[0]);
  }
  return [...families];
}

async function waitForProjectRichTextFonts(projectPath: string, project: PaideiaProject | null, fonts: LessonCustomFont[]) {
  if (!document.fonts) return;
  const waits = projectRichTextFontFamilies(projectPath, project, fonts).map((family) => {
    const load = document.fonts.load(`400 16px "${family}"`).catch(() => [] as FontFace[]);
    const timeout = new Promise<FontFace[]>((resolve) => window.setTimeout(() => resolve([]), 1200));
    return Promise.race([load, timeout]);
  });
  await Promise.all(waits);
}

function blockSpacingStyle(activityPadding: number): CSSProperties | undefined {
  return {
    "--block-activity-padding": `${activityPadding}px`
  } as CSSProperties;
}

function normalizeProjectTitle(value: string) {
  return value.replace(/\u2500+/g, " ").replace(/\s+/g, " ").trim() || "Leçon PAIDEIA";
}

function defaultCourseCoverTitleHtml(title?: string | null) {
  const wrapper = document.createElement("div");
  const paragraph = document.createElement("p");
  paragraph.style.color = DEFAULT_COURSE_TITLE_STYLE.color;
  paragraph.style.fontSize = DEFAULT_COURSE_TITLE_STYLE.fontSize;
  paragraph.style.fontWeight = DEFAULT_COURSE_TITLE_STYLE.fontWeight;
  paragraph.textContent = normalizeProjectTitle(title ?? "");
  wrapper.appendChild(paragraph);
  return wrapper.innerHTML;
}

function normalizeCourseCoverTitleHtml(value: string | null | undefined, fallbackTitle?: string | null) {
  const normalized = decorateRichTextSeparatorsInHtml(
    normalizeFrenchTypographyInHtml(value?.trim() || defaultCourseCoverTitleHtml(fallbackTitle)),
  );
  const plainText = stripHtmlForEditor(normalized).replace(/\s+\n/g, "\n").replace(/\n\s+/g, "\n").trim();
  if (!plainText || plainText === COURSE_COVER_TITLE_PLACEHOLDER) {
    return "";
  }
  return normalized;
}

function resolveCourseCoverTitleHtml(value: string | null | undefined, fallbackTitle?: string | null) {
  return normalizeCourseCoverTitleHtml(value, fallbackTitle) || defaultCourseCoverTitleHtml(fallbackTitle);
}

function defaultCourseCoverFallbackTitle() {
  return "Leçon";
}

function moveCaretToEnd(node: HTMLElement) {
  const selection = window.getSelection();
  if (!selection) {
    return;
  }
  const range = document.createRange();
  range.selectNodeContents(node);
  range.collapse(false);
  selection.removeAllRanges();
  selection.addRange(range);
}

function setPaideiaDragShieldActive(active: boolean) {
  document.documentElement.classList.toggle("paideia-pointer-drag-active", active);
  window.dispatchEvent(
    new CustomEvent("paideia:set-external-iframe-suspended", {
      detail: { suspended: active }
    })
  );
}

// Rollback switch: restore manual loading if an external provider proves unstable.
const REQUIRE_MANUAL_EXTERNAL_IFRAME_ACTIVATION = false;

function waitForNextPaint() {
  return new Promise<void>((resolve) => {
    window.requestAnimationFrame(() => window.requestAnimationFrame(() => resolve()));
  });
}

function buildLibraryImageUrl(imagePath?: string | null) {
  if (!imagePath) {
    return null;
  }

  if (/^(data:|https?:|asset:)/i.test(imagePath)) {
    return imagePath;
  }

  if (isTauri()) {
    return convertFileSrc(imagePath);
  }

  return `/@fs/${encodeFsPath(imagePath)}`;
}

function blockWithCourseAppearance(block: PaideiaBlock, project?: PaideiaProject | null): PaideiaBlock {
  return resolveBlockCourseAppearance(block, project?.courseAppearance);
}

function comparableProjectPath(value: string) {
  return value.replace(/\\/g, "/").replace(/\/+$/, "").toLocaleLowerCase("en-US");
}

function isLegacySharedWorkspace(path: string): boolean {
  return /\/collaboration\/(?:workspaces|temp_edit)(?:\/|$)/i.test(path.replace(/\\/g, "/"));
}

function libraryProjectPreferenceKey(entry: LibraryProjectEntry) {
  const collaborationLibraryKey = entry.collaborationLibraryInstanceId || entry.collaborationLibraryId;
  return collaborationLibraryKey && entry.collaborationId
    ? `collaboration:${collaborationLibraryKey}:${entry.collaborationId}`
    : entry.archivePath;
}

