  function resizeCourseTitleField(field: HTMLTextAreaElement) {
    const nextValue = field.value.split(/\r?\n/).slice(0, 2).join("\n");
    if (field.value !== nextValue) {
      field.value = nextValue;
    }
    field.style.height = "auto";
    field.style.height = `${Math.min(field.scrollHeight, field.offsetHeight || 180)}px`;
  }

