  useEffect(() => {
    if (!("PerformanceObserver" in window)) {
      return;
    }

    type LayoutShiftEntry = PerformanceEntry & {
      hadRecentInput?: boolean;
      sources?: Array<{ node?: Node | null }>;
      value?: number;
    };

    const observers: PerformanceObserver[] = [];
    const supportedTypes = PerformanceObserver.supportedEntryTypes ?? [];

    if (supportedTypes.includes("layout-shift")) {
      const layoutObserver = new PerformanceObserver((list) => {
        for (const entry of list.getEntries() as LayoutShiftEntry[]) {
          if (entry.hadRecentInput || (entry.value ?? 0) < 0.02) {
            continue;
          }
          const sources = (entry.sources ?? []).slice(0, 4).map((source) => {
            const node = source.node;
            if (!(node instanceof HTMLElement)) {
              return node?.nodeName ?? "unknown";
            }
            return `${node.tagName.toLowerCase()}${node.id ? `#${node.id}` : ""}${
              node.classList.length ? `.${Array.from(node.classList).slice(0, 3).join(".")}` : ""
            }`;
          });
          void logDevEvent("warn", "performance.layout-shift", {
            sources,
            value: Number((entry.value ?? 0).toFixed(4))
          });
        }
      });
      layoutObserver.observe({ type: "layout-shift", buffered: true });
      observers.push(layoutObserver);
    }

    if (supportedTypes.includes("longtask")) {
      const longTaskObserver = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          if (entry.duration < 80) {
            continue;
          }
          void logDevEvent("warn", "performance.long-task", {
            durationMs: Math.round(entry.duration),
            startTimeMs: Math.round(entry.startTime)
          });
        }
      });
      longTaskObserver.observe({ type: "longtask", buffered: true });
      observers.push(longTaskObserver);
    }

    return () => observers.forEach((observer) => observer.disconnect());
  }, []);

