  useEffect(() => {
    if (!pendingLibraryCollectionDrag) {
      return;
    }

    const updateHoveredProject = (clientX: number, clientY: number) => {
      const target = document.elementFromPoint(clientX, clientY);
      const card = target?.closest<HTMLElement>("[data-library-archive-path]");
      setHoveredLibraryDropArchive(card?.dataset.libraryArchivePath ?? null);
      return card?.dataset.libraryArchivePath ?? "";
    };

    let pointerX = pendingLibraryCollectionDrag.x;
    let pointerY = pendingLibraryCollectionDrag.y;
    const activateDrag = () => {
      if (draggedLibraryCollectionRef.current) return;
      draggedLibraryCollectionRef.current = pendingLibraryCollectionDrag.collection;
      setKeywordDragGhost({ keyword: pendingLibraryCollectionDrag.collection, x: pointerX, y: pointerY, label: !pendingLibraryCollectionDrag.keyword });
      if (!pendingLibraryCollectionDrag.keyword) setDraggedLibraryCollection(pendingLibraryCollectionDrag.collection);
    };
    const holdTimer = pendingLibraryCollectionDrag.keyword
      ? window.setTimeout(activateDrag, 250) : null;
    const clearHold = () => { if (holdTimer !== null) window.clearTimeout(holdTimer); };
    const moveCollectionDrag = (event: PointerEvent) => {
      pointerX = event.clientX;
      pointerY = event.clientY;
      const distance = Math.hypot(pointerX - pendingLibraryCollectionDrag.x, pointerY - pendingLibraryCollectionDrag.y);
      if (distance > 6) activateDrag();
      if (draggedLibraryCollectionRef.current) {
        updateHoveredProject(pointerX, pointerY);
        if (keywordDragGhostRef.current) {
          keywordDragGhostRef.current.style.transform = `translate3d(${pointerX + 12}px, ${pointerY + 12}px, 0)`;
        }
      }
    };

    const finishCollectionDrop = (event: PointerEvent) => {
      clearHold();
      setKeywordDragGhost(null);
      const collection = draggedLibraryCollectionRef.current;
      const archivePath = collection ? updateHoveredProject(event.clientX, event.clientY) : "";
      if (collection) {
        suppressLibraryCollectionClickRef.current = true;
        window.setTimeout(() => {
          suppressLibraryCollectionClickRef.current = false;
        }, 0);
        if (archivePath) {
          if (pendingLibraryCollectionDrag.keyword) assignDroppedLibraryKeyword(archivePath, collection);
          else assignLibraryCollection(archivePath, collection);
        }
      }
      draggedLibraryCollectionRef.current = null;
      setDraggedLibraryCollection(null);
      setPendingLibraryCollectionDrag(null);
      setHoveredLibraryDropArchive(null);
    };

    const cancelCollectionDrop = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        clearHold();
        setKeywordDragGhost(null);
        draggedLibraryCollectionRef.current = null;
        setDraggedLibraryCollection(null);
        setPendingLibraryCollectionDrag(null);
        setHoveredLibraryDropArchive(null);
      }
    };

    const cancelPointerDrop = () => {
      clearHold();
      setKeywordDragGhost(null);
      draggedLibraryCollectionRef.current = null;
      setDraggedLibraryCollection(null);
      setPendingLibraryCollectionDrag(null);
      setHoveredLibraryDropArchive(null);
    };
    window.addEventListener("pointercancel", cancelPointerDrop, true);
    window.addEventListener("pointermove", moveCollectionDrag, true);
    window.addEventListener("pointerup", finishCollectionDrop, true);
    window.addEventListener("keydown", cancelCollectionDrop, true);
    return () => {
      clearHold();
      window.removeEventListener("pointercancel", cancelPointerDrop, true);
      window.removeEventListener("pointermove", moveCollectionDrag, true);
      window.removeEventListener("pointerup", finishCollectionDrop, true);
      window.removeEventListener("keydown", cancelCollectionDrop, true);
    };
  }, [pendingLibraryCollectionDrag, libraryCollectionOverrides, libraryProjects]);

