    let cancelled = false;

    async function bootstrap() {
      const projectPathToLoad = currentProjectPath;

      if (!projectPathToLoad) {
        return;
      }

      const loadedWorkspaceState = await loadLocalizedWorkspace(projectPathToLoad);

      if (cancelled) {
        return;
      }

      setLessonOpeningFontsPending(true);
      setWorkspaceStateProjectPath(projectPathToLoad);
      setWorkspaceState(loadedWorkspaceState);
      if (projectPathToLoad !== getDefaultProjectPath()) {
        upsertProjectTab(projectPathToLoad, loadedWorkspaceState.project.title);
        rememberRecentLesson(projectPathToLoad);
      }
      void logDevEvent("info", "Projet chargé", {
        projectPath: projectPathToLoad,
        projectId: loadedWorkspaceState.project.id,
        projectTitle: loadedWorkspaceState.project.title
      });
      if (projectPathToLoad !== currentProjectPath) {
        setCurrentProjectPath(projectPathToLoad);
      }
      const firstPage = flattenPages(loadedWorkspaceState.project)[0];
      setActivePageId((current) => current || firstPage?.id || "");
    }

    void bootstrap().catch((error) => {
      if (!cancelled) {
        setImportDialog({
          status: "error",
          doneTitle: t("import.openingInterrupted"),
          message: error instanceof Error ? error.message : t("import.openingError")
        });
      }
    });

    return () => {
      cancelled = true;
    };
