  useEffect(() => {
    if (!isPreviewMode || !isPreviewStarted || !activePage) {
      return;
    }

    const passiveBlocks = activePage.blocks.filter((block) => block.type !== "complete" && block.type !== "card-sort" && block.type !== "matching" && isPassiveCompletionBlock(block));
    const passiveBlockIds = new Set(passiveBlocks.map((block) => block.id));
    const previewWindow = previewViewportWindow();
    const previewDocument = previewViewportDocument();
    const IntersectionObserverConstructor = (previewWindow as Window & typeof globalThis).IntersectionObserver;
    if (!passiveBlockIds.size || !IntersectionObserverConstructor) {
      return;
    }
    const lastPassiveBlockId = passiveBlocks[passiveBlocks.length - 1]?.id ?? "";
    const isLastChapter = activeChapterIndex >= 0 && activeChapterIndex === chapterEntries.length - 1;

    const viewThresholds = Array.from({ length: 36 }, (_, index) => index / 100);
    const observer = new IntersectionObserverConstructor(
      (entries: IntersectionObserverEntry[]) => {
        setPreviewCompletedBlocks((current) => {
          let changed = false;
          const next = { ...current };
          for (const entry of entries) {
            const targetHeight = Math.max(1, entry.boundingClientRect.height || 0);
            const viewportHeight = Math.max(1, previewWindow.innerHeight || previewDocument.documentElement.clientHeight || 0);
            const requiredVisibleHeight = Math.min(
              targetHeight * 0.35,
              Math.min(180, Math.max(96, viewportHeight * 0.25))
            );
            if (!entry.isIntersecting || entry.intersectionRect.height + 0.75 < requiredVisibleHeight) {
              continue;
            }
            const blockId = (entry.target as HTMLElement).getAttribute("data-block-id") || "";
            if (!blockId || !passiveBlockIds.has(blockId) || next[blockId]) {
              continue;
            }
            if (isLastChapter && blockId === lastPassiveBlockId) {
              for (const passiveBlock of passiveBlocks) {
                if (!next[passiveBlock.id]) {
                  next[passiveBlock.id] = true;
                  changed = true;
                }
              }
              continue;
            }
            next[blockId] = true;
            changed = true;
          }
          return changed ? next : current;
        });
      },
      { threshold: viewThresholds }
    );

    const observeRenderedBlocks = () => {
      activePage.blocks.forEach((block) => {
        if (!passiveBlockIds.has(block.id)) return;
        const element = previewDocument.querySelector<HTMLElement>(`[data-block-id="${block.id}"]`);
        if (element) observer.observe(element);
      });
    };
    observeRenderedBlocks();
    const MutationObserverConstructor = (previewWindow as Window & typeof globalThis).MutationObserver ?? MutationObserver;
    const renderObserver = new MutationObserverConstructor(observeRenderedBlocks);
    renderObserver.observe(previewDocument.body, { childList: true, subtree: true });

    return () => {
      renderObserver.disconnect();
      observer.disconnect();
    };
  }, [
    activePage,
    activeChapterIndex,
    canRewindPreview,
    isPreviewMode,
    isPreviewResponsiveViewport,
    isPreviewStarted,
    chapterEntries.length,
    previewVisibleEndIndex,
    previewVisibleStartIndex
  ]);

