  function clearActivityControlsTimers() {
    if (activityControlsGraceTimerRef.current !== null) {
      window.clearTimeout(activityControlsGraceTimerRef.current);
      activityControlsGraceTimerRef.current = null;
    }
    if (activityControlsFadeTimerRef.current !== null) {
      window.clearTimeout(activityControlsFadeTimerRef.current);
      activityControlsFadeTimerRef.current = null;
    }
  }

  function activateActivityControls(blockId: string) {
    if (isPreviewMode || (isInspectorOpen && selectedBlockId === blockId)) {
      return;
    }
    clearActivityControlsTimers();
    setActivityControls({ blockId, phase: "active" });
  }

  function lockActivityControls(blockId: string, phase: "dragging" | "menu-open") {
    clearActivityControlsTimers();
    setActivityControls({ blockId, phase });
  }

  function scheduleActivityControlsHide(blockId: string, unlock = false) {
    clearActivityControlsTimers();
    setActivityControls((current) => {
      if (!current || current.blockId !== blockId || (!unlock && (current.phase === "dragging" || current.phase === "menu-open"))) {
        return current;
      }
      return { blockId, phase: "grace" };
    });
    activityControlsGraceTimerRef.current = window.setTimeout(() => {
      activityControlsGraceTimerRef.current = null;
      setActivityControls((current) => {
        if (!current || current.blockId !== blockId || current.phase !== "grace") {
          return current;
        }
        return { blockId, phase: "fading" };
      });
      activityControlsFadeTimerRef.current = window.setTimeout(() => {
        activityControlsFadeTimerRef.current = null;
        setActivityControls((current) => current?.blockId === blockId && current.phase === "fading" ? null : current);
      }, 180);
    }, 700);
  }

  const persistBlockPaddingOffset = useCallback(async (blockId: string, nextOffset: number, nextHeaderHeight?: number | null) => {
    if (!activePage) {
      return;
    }

    const block = activePage.blocks.find((item) => item.id === blockId);
    if (!block) {
      return;
    }

    const basePadding = blockBasePadding(block, currentLessonActivitySpacing);
    const minimumPadding = blockMinimumActivityPadding(block);
    const maximumPadding = blockMaximumActivityPadding(block);
    const previousOffset = clampBlockPaddingOffset(block.paddingOffset, basePadding, minimumPadding, maximumPadding);
    const normalizedOffset = clampBlockPaddingOffset(nextOffset, basePadding, minimumPadding, maximumPadding);
    const renderedHeaderHeight = block.type === "header"
      ? Array.from(document.querySelectorAll<HTMLElement>("[data-block-id]"))
          .find((element) => element.dataset.blockId === blockId)
          ?.querySelector<HTMLElement>(".header-banner")
          ?.getBoundingClientRect().height ?? null
      : null;
    const resolvedHeaderHeight = block.type === "header"
      ? Math.max(70, Math.round(
          Number.isFinite(nextHeaderHeight)
            ? Number(nextHeaderHeight)
            : adjustedHeaderHeight(
                renderedHeaderHeight ?? 240,
                Math.max(minimumPadding, basePadding + previousOffset),
                Math.max(minimumPadding, basePadding + normalizedOffset)
              )
        ))
      : null;
    const updateInput = buildUpdateBlockInputFromBlock(block, {
      paddingOffset: normalizedOffset,
      ...(resolvedHeaderHeight != null ? { headerHeight: `${resolvedHeaderHeight}px` } : {})
    });
    if (!updateInput) {
      return;
    }

    setBlockPaddingOffsetDrafts((current) => ({ ...current, [blockId]: normalizedOffset }));
    if (resolvedHeaderHeight != null) {
      setBlockHeaderHeightDrafts((current) => ({ ...current, [blockId]: `${resolvedHeaderHeight}px` }));
    }

    try {
      const nextState = await updateBlock(updateInput);
      setWorkspaceState(nextState);
      setBlockPaddingOffsetDrafts((current) => {
        const next = { ...current };
        delete next[blockId];
        return next;
      });
      setBlockHeaderHeightDrafts((current) => {
        const next = { ...current };
        delete next[blockId];
        return next;
      });
    } catch (error) {
      setBlockPaddingOffsetDrafts((current) => {
        const next = { ...current };
        if (previousOffset === 0) {
          delete next[blockId];
        } else {
          next[blockId] = previousOffset;
        }
        return next;
      });
      setBlockHeaderHeightDrafts((current) => {
        const next = { ...current };
        delete next[blockId];
        return next;
      });
      throw error;
    }
  }, [activePage, buildUpdateBlockInputFromBlock, currentLessonActivitySpacing]);

  function startPaddingControlDrag(event: ReactPointerEvent<HTMLElement>, block: PaideiaBlock) {
    if (isPreviewMode || event.button !== 0) {
      return;
    }

    const basePadding = blockBasePadding(block, currentLessonActivitySpacing);
    const minimumPadding = blockMinimumActivityPadding(block);
    const maximumPadding = blockMaximumActivityPadding(block);
    const startOffset = clampBlockPaddingOffset(
      blockPaddingOffsetDrafts[block.id] ?? block.paddingOffset,
      basePadding,
      minimumPadding,
      maximumPadding
    );
    const startHeaderHeight = block.type === "header"
      ? event.currentTarget.closest(".block-stack-item")
          ?.querySelector<HTMLElement>(".header-banner")
          ?.getBoundingClientRect().height ?? null
      : null;

    event.preventDefault();
    event.stopPropagation();
    event.currentTarget.setPointerCapture(event.pointerId);
    paddingControlPointerCaptureRef.current = {
      element: event.currentTarget,
      pointerId: event.pointerId
    };
    setSelectedBlockId(block.id);
    setActivePaddingControlBlockId(block.id);

    const nextDrag = {
      blockId: block.id,
      pageId: activePage?.id ?? "",
      startY: event.clientY,
      startOffset,
      currentOffset: startOffset,
      basePadding,
      minimumPadding,
      maximumPadding,
      startHeaderHeight,
      currentHeaderHeight: startHeaderHeight
    };
    paddingControlDragRef.current = nextDrag;
    setPaddingControlDrag(nextDrag);
    setBlockPaddingOffsetDrafts((current) => ({ ...current, [block.id]: startOffset }));
    if (startHeaderHeight != null) {
      setBlockHeaderHeightDrafts((current) => ({ ...current, [block.id]: `${Math.round(startHeaderHeight)}px` }));
    }
  }

  async function applyBlockImageAccessibility(value: { altText: string; decorative: boolean }) {
    if (imageAltDialogItemId) {
      setBlockForm((current) => ({
        ...current,
        activityItems: current.activityItems.map((item) => item.id === imageAltDialogItemId
          ? imageAltDialogItemFace === "front"
            ? { ...item, frontImageAccessibility: value }
            : imageAltDialogItemFace === "back"
              ? { ...item, backImageAccessibility: value }
              : { ...item, imageAccessibility: value }
          : item)
      }));
      setImageAltDialogBlockId(null);
      setImageAltDialogItemId(null);
      setImageAltDialogItemFace(null);
      return;
    }
    const block = activePage?.blocks.find((candidate) => candidate.id === imageAltDialogBlockId);
    if (!block) {
      setImageAltDialogBlockId(null);
      return;
    }
    if (isInspectorOpen && selectedBlockId === block.id) {
      setBlockForm((current) => ({ ...current, imageAccessibility: value }));
      setImageAltDialogBlockId(null);
      return;
    }
    const input = buildUpdateBlockInputFromBlock(block, { imageAccessibility: value });
    if (!input) return;
    await runAction("update-image-alt", async () => {
      const nextState = await updateBlock(input);
      setWorkspaceState(nextState);
      if (selectedBlockId === block.id) {
        setBlockForm((current) => ({ ...current, imageAccessibility: value }));
      }
      setImageAltDialogBlockId(null);
    });
  }

  async function runDragMutation(
    source: string,
    details: Record<string, unknown>,
    work: () => Promise<void>
  ) {
    if (dragMutationInFlightRef.current) {
      void logDevEvent("warn", "Drag/drop ignoré car une mutation est déjà en cours", {
        source,
        ...details
      });
      return;
    }

    dragMutationInFlightRef.current = true;
    setPaideiaDragShieldActive(true);
    void logDevEvent("info", "Drag/drop mutation démarrée", {
      source,
      ...details
    });
    try {
      await work();
      void logDevEvent("info", "Drag/drop mutation terminée", {
        source,
        ...details
      });
    } catch (error) {
      void logDevEvent("error", "Drag/drop mutation en échec", {
        source,
        ...details,
        error: error instanceof Error ? error.message : String(error),
        stack: error instanceof Error ? error.stack : null
      });
      throw error;
    } finally {
      dragMutationInFlightRef.current = false;
      setPaideiaDragShieldActive(false);
    }
  }

