  const showEditorDropZones = hasPointerDrag || isCanvasDropActive;

  useEffect(() => {
    const active = pointerDrag?.kind === "move" || hasChapterPointerDrag;
    document.documentElement.classList.toggle("paideia-move-handle-drag-active", active);
    return () => document.documentElement.classList.remove("paideia-move-handle-drag-active");
  }, [hasChapterPointerDrag, pointerDrag?.kind]);

  useEffect(() => {
    if (!hasChapterPointerDrag) {
      return;
    }

    function resetChapterPointerDrag() {
      chapterPointerDragRef.current = null;
      setChapterPointerDrag(null);
      setChapterDropTarget(null);
    }

    function handlePointerMove(event: PointerEvent) {
      const current = chapterPointerDragRef.current;
      if (!current) {
        return;
      }

      const distance = Math.hypot(event.clientX - current.startX, event.clientY - current.startY);
      const nextDrag = {
        ...current,
        x: event.clientX,
        y: event.clientY,
        active: current.active || distance > 3
      };
      chapterPointerDragRef.current = nextDrag;
      if (!current.active && nextDrag.active) {
        setChapterPointerDrag(nextDrag);
      } else if (chapterPointerDragGhostRef.current) {
        chapterPointerDragGhostRef.current.style.left = `${event.clientX + 14}px`;
        chapterPointerDragGhostRef.current.style.top = `${event.clientY + 14}px`;
      }

      if (nextDrag.active) {
        event.preventDefault();
        setChapterDropTarget(getChapterPointerDropTarget(event.clientX, event.clientY, nextDrag.moduleId));
      }
    }

    function handlePointerUp(event: PointerEvent) {
      const current = chapterPointerDragRef.current;
      const target = current?.active
        ? getChapterPointerDropTarget(event.clientX, event.clientY, current.moduleId)
        : null;
      resetChapterPointerDrag();

      if (!current?.active || !target) {
        setPaideiaDragShieldActive(false);
        return;
      }

      const entry = chapterEntries.find(
        (candidate) => candidate.module.id === current.moduleId && candidate.chapter.id === current.chapterId
      );
      if (!entry) {
        setPaideiaDragShieldActive(false);
        return;
      }

      const currentIndex = entry.module.chapters.findIndex((chapter) => chapter.id === current.chapterId);
      const adjustedTargetIndex = currentIndex < target.index ? target.index - 1 : target.index;
      if (currentIndex < 0 || currentIndex === adjustedTargetIndex) {
        setPaideiaDragShieldActive(false);
        return;
      }

      void runDragMutation(
        "chapter-pointer-drop",
        {
          action: "move-chapter",
          chapterId: current.chapterId,
          moduleId: current.moduleId,
          targetIndex: adjustedTargetIndex
        },
        async () => {
          await handleReorderChapter(entry, adjustedTargetIndex);
        }
      );
    }

    function handlePointerCancel() {
      resetChapterPointerDrag();
      setPaideiaDragShieldActive(false);
    }

    function handleKeyDown(event: globalThis.KeyboardEvent) {
      if (event.key !== "Escape") {
        return;
      }
      event.preventDefault();
      handlePointerCancel();
    }

    window.addEventListener("pointermove", handlePointerMove, { passive: false });
    window.addEventListener("pointerup", handlePointerUp);
    window.addEventListener("pointercancel", handlePointerCancel);
    window.addEventListener("keydown", handleKeyDown, true);
    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", handlePointerUp);
      window.removeEventListener("pointercancel", handlePointerCancel);
      window.removeEventListener("keydown", handleKeyDown, true);
    };
  }, [hasChapterPointerDrag, chapterEntries, currentProjectPath]);

  useEffect(() => {
    if (!hasPointerDrag) {
      return;
    }

    function handlePointerMove(event: PointerEvent) {
      const current = pointerDragRef.current;
      if (!current) {
        return;
      }

      const distance = Math.hypot(event.clientX - current.startX, event.clientY - current.startY);
      const nextDrag = {
        ...current,
        x: event.clientX,
        y: event.clientY,
        active: current.active || distance > 3
      };
      pointerDragRef.current = nextDrag;
      if (!current.active && nextDrag.active) {
        setPointerDrag(nextDrag);
      } else if (pointerDragGhostRef.current) {
        pointerDragGhostRef.current.style.left = `${event.clientX + 14}px`;
        pointerDragGhostRef.current.style.top = `${event.clientY + 14}px`;
      }

      if (nextDrag.active) {
        event.preventDefault();
        schedulePointerDropVisual(event.clientX, event.clientY);
      }
    }

    function handlePointerUp(event: PointerEvent) {
      const current = pointerDragRef.current;
      cancelScheduledPointerDropVisual();
      const capturedTargetIndex = current?.active ? getPointerDropIndex(event.clientX, event.clientY) : null;
      pointerDragRef.current = null;
      setPointerDrag(null);
      setPointerDropVisual(null);
      if (current?.kind === "move" && current.blockId) {
        scheduleActivityControlsHide(current.blockId, true);
      }

      if (!current) {
        setPaideiaDragShieldActive(false);
        return;
      }

      if (!current.active) {
        setPaideiaDragShieldActive(false);
        return;
      }

      suppressNextActivityCreateClickRef.current = true;
      window.setTimeout(() => {
        suppressNextActivityCreateClickRef.current = false;
      }, 0);

      const favoriteTargetIndex = getFavoriteDropIndex(event.clientX, event.clientY);
      if (favoriteTargetIndex !== null && current.kind === "favorite" && current.favoriteIndex !== undefined) {
        reorderActivityFavorite(current.favoriteIndex, favoriteTargetIndex);
        setPaideiaDragShieldActive(false);
        return;
      }

      if (favoriteTargetIndex !== null && current.kind === "new" && current.blockType) {
        addActivityFavorite(current.blockType, favoriteTargetIndex);
        setPaideiaDragShieldActive(false);
        return;
      }

      const targetIndex = capturedTargetIndex;
      if (targetIndex === null) {
        setPaideiaDragShieldActive(false);
        return;
      }

      if (current.kind === "new" && current.blockType) {
        const blockType = current.blockType;
        void runDragMutation("pointer-drop", { action: "create", blockType, targetIndex }, async () => {
          await handleCreateBlock(blockType, targetIndex, { openEditor: false });
        });
        return;
      }

      if (current.kind === "favorite" && current.favoriteType) {
        const favoriteType = current.favoriteType;
        void runDragMutation("pointer-drop", { action: "create-from-favorite", blockType: favoriteType, targetIndex }, async () => {
          await handleCreateBlock(favoriteType, targetIndex, { openEditor: false });
        });
        return;
      }

      if (current.kind === "move" && current.blockId) {
        const blockId = current.blockId;
        void runDragMutation("pointer-drop", { action: "move", blockId, targetIndex }, async () => {
          await handleReorderBlock(blockId, targetIndex);
        });
        return;
      }

      setPaideiaDragShieldActive(false);
    }

    window.addEventListener("pointermove", handlePointerMove, { passive: false });
    window.addEventListener("pointerup", handlePointerUp);
    window.addEventListener("pointercancel", handlePointerUp);
    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", handlePointerUp);
      window.removeEventListener("pointercancel", handlePointerUp);
    };
  }, [hasPointerDrag, activePage, currentProjectPath]);

  useEffect(() => {
    const shouldAutoScroll =
      hasPointerDrag ||
      hasActiveChapterPointerDrag ||
      Boolean(draggedBlockId) ||
      Boolean(draggedFavoriteType) ||
      isCanvasDropActive;
    if (!shouldAutoScroll || isPreviewMode) {
      return;
    }

    const edgeSize = 110;
    const maxSpeed = 5;
    let lastClientY: number | null =
      pointerDragRef.current?.y ??
      (chapterPointerDragRef.current?.active ? chapterPointerDragRef.current.y : null);
    let frame = 0;

    function getDragScrollContainer() {
      return document.querySelector<HTMLElement>(".workspace-shell .authoring-stage")
        ?? document.querySelector<HTMLElement>(".authoring-stage")
        ?? null;
    }

    function getDragAutoScrollRect(scrollContainer: HTMLElement | null) {
      const containerRect = scrollContainer?.getBoundingClientRect() ?? {
        top: 0,
        bottom: window.innerHeight || document.documentElement.clientHeight
      };
      if (hasActiveChapterPointerDrag) {
        return containerRect;
      }
      const editorRect = document.querySelector<HTMLElement>(
        ".editor-section"
      )?.getBoundingClientRect();
      if (!editorRect) {
        return containerRect;
      }
      return {
        top: Math.max(containerRect.top, editorRect.top),
        bottom: Math.min(containerRect.bottom, editorRect.bottom)
      };
    }

    function updatePointerY(clientY: number) {
      lastClientY = clientY;
    }

    function tick() {
      frame = window.requestAnimationFrame(tick);
      if (lastClientY === null) {
        return;
      }

      const scrollContainer = getDragScrollContainer();
      const containerRect = getDragAutoScrollRect(scrollContainer);
      if (lastClientY < containerRect.top || lastClientY > containerRect.bottom) {
        return;
      }
      let direction = 0;
      let intensity = 0;
      if (lastClientY < containerRect.top + edgeSize) {
        direction = -1;
        intensity = (containerRect.top + edgeSize - lastClientY) / edgeSize;
      } else if (lastClientY > containerRect.bottom - edgeSize) {
        direction = 1;
        intensity = (lastClientY - (containerRect.bottom - edgeSize)) / edgeSize;
      }

      if (!direction || intensity <= 0) {
        return;
      }

      const currentChapterDrag = chapterPointerDragRef.current;
      if (direction < 0 && currentChapterDrag?.active && currentChapterDrag.sourceIndex === 0) {
        return;
      }

      const easedIntensity = intensity * intensity * intensity;
      const speed = Math.max(1, Math.ceil(Math.min(maxSpeed, easedIntensity * maxSpeed))) * direction;
      if (scrollContainer) {
        scrollContainer.scrollBy({ top: speed, left: 0, behavior: "auto" });
      } else {
        window.scrollBy({ top: speed, left: 0, behavior: "auto" });
      }

      const currentPointerDrag = pointerDragRef.current;
      if (currentPointerDrag?.active) {
        schedulePointerDropVisual(currentPointerDrag.x, currentPointerDrag.y);
      }
      if (currentChapterDrag?.active) {
        setChapterDropTarget(
          getChapterPointerDropTarget(currentChapterDrag.x, currentChapterDrag.y, currentChapterDrag.moduleId)
        );
      }
    }

    function handlePointerMove(event: PointerEvent) {
      updatePointerY(event.clientY);
    }

    function handleDragOver(event: globalThis.DragEvent) {
      updatePointerY(event.clientY);
    }

    window.addEventListener("pointermove", handlePointerMove, { passive: true });
    window.addEventListener("dragover", handleDragOver, { passive: true });
    frame = window.requestAnimationFrame(tick);
    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("dragover", handleDragOver);
      window.cancelAnimationFrame(frame);
    };
  }, [hasPointerDrag, hasActiveChapterPointerDrag, draggedBlockId, draggedFavoriteType, isCanvasDropActive, isPreviewMode, activePage]);

  useEffect(() => () => clearActivityControlsTimers(), []);

  useEffect(() => {
    if (!isActivityPastePlacementActive) {
      return;
    }

    function handlePendingActivityPasteKeyDown(event: KeyboardEvent) {
      if (event.key !== "Escape" || event.defaultPrevented) {
        return;
      }
      event.preventDefault();
      setActivityClipboard(null);
      setIsActivityPastePlacementActive(false);
      setActivityPasteCount(0);
      setPasteActivityDialog(null);
    }

    window.addEventListener("keydown", handlePendingActivityPasteKeyDown, true);
    return () => window.removeEventListener("keydown", handlePendingActivityPasteKeyDown, true);
  }, [isActivityPastePlacementActive]);

  useEffect(() => {
    if (isPreviewMode || isInspectorOpen) {
      clearActivityControlsTimers();
      setActivityControls(null);
    }
  }, [isPreviewMode, isInspectorOpen]);

  useEffect(() => {
    if (!paddingControlDrag) {
      return;
    }

    let cancelled = false;

    function releasePointerCapture() {
      const capture = paddingControlPointerCaptureRef.current;
      paddingControlPointerCaptureRef.current = null;
      if (capture?.element.hasPointerCapture(capture.pointerId)) {
        capture.element.releasePointerCapture(capture.pointerId);
      }
    }

    function finishDrag(commit: boolean) {
      const current = paddingControlDragRef.current;
      paddingControlDragRef.current = null;
      releasePointerCapture();
      setPaddingControlDrag(null);
      if (!current) {
        return;
      }

      if (!commit || cancelled) {
        setBlockPaddingOffsetDrafts((drafts) => {
          const next = { ...drafts };
          delete next[current.blockId];
          return next;
        });
        setBlockHeaderHeightDrafts((drafts) => {
          const next = { ...drafts };
          delete next[current.blockId];
          return next;
        });
        return;
      }

      void persistBlockPaddingOffset(current.blockId, current.currentOffset, current.currentHeaderHeight);
    }

    function handlePointerMove(event: PointerEvent) {
      const current = paddingControlDragRef.current;
      if (!current) {
        return;
      }

      event.preventDefault();
      const deltaY = current.startY - event.clientY;
      const nextOffset = clampBlockPaddingOffset(
        current.startOffset + deltaY,
        current.basePadding,
        current.minimumPadding,
        current.maximumPadding
      );
      const nextHeaderHeight = current.startHeaderHeight == null
        ? null
        : adjustedHeaderHeight(
            current.startHeaderHeight,
            Math.max(current.minimumPadding, current.basePadding + current.startOffset),
            Math.max(current.minimumPadding, current.basePadding + nextOffset)
          );
      const nextDrag = { ...current, currentOffset: nextOffset, currentHeaderHeight: nextHeaderHeight };
      paddingControlDragRef.current = nextDrag;
      setPaddingControlDrag(nextDrag);
      setBlockPaddingOffsetDrafts((drafts) => ({ ...drafts, [current.blockId]: nextOffset }));
      if (nextHeaderHeight != null) {
        setBlockHeaderHeightDrafts((drafts) => ({ ...drafts, [current.blockId]: `${Math.round(nextHeaderHeight)}px` }));
      }
    }

    function handlePointerUp() {
      finishDrag(true);
    }

    function handlePointerCancel() {
      cancelled = true;
      finishDrag(false);
    }

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        cancelled = true;
        event.preventDefault();
        finishDrag(false);
      }
    }

    window.addEventListener("pointermove", handlePointerMove, { passive: false });
    window.addEventListener("pointerup", handlePointerUp);
    window.addEventListener("pointercancel", handlePointerCancel);
    window.addEventListener("keydown", handleKeyDown, true);
    return () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", handlePointerUp);
      window.removeEventListener("pointercancel", handlePointerCancel);
      window.removeEventListener("keydown", handleKeyDown, true);
    };
  }, [paddingControlDrag, persistBlockPaddingOffset]);

  useEffect(() => {
    if (!paddingControlDrag) {
      return;
    }

    document.documentElement.classList.add("padding-control-dragging");
    return () => {
      document.documentElement.classList.remove("padding-control-dragging");
      const capture = paddingControlPointerCaptureRef.current;
      if (capture?.element.hasPointerCapture(capture.pointerId)) {
        capture.element.releasePointerCapture(capture.pointerId);
      }
      paddingControlPointerCaptureRef.current = null;
    };
  }, [paddingControlDrag !== null]);

  useEffect(() => {
    function handleOutsidePaddingControlPointerDown(event: PointerEvent) {
      const target = event.target as HTMLElement | null;
      if (target?.closest(".block-padding-control")) {
        return;
      }
      setActivePaddingControlBlockId(null);
    }

    document.addEventListener("pointerdown", handleOutsidePaddingControlPointerDown, true);
    return () => document.removeEventListener("pointerdown", handleOutsidePaddingControlPointerDown, true);
  }, []);

  useEffect(() => {
    const clearDragShield = () => setPaideiaDragShieldActive(false);
    window.addEventListener("dragend", clearDragShield, true);
    window.addEventListener("drop", clearDragShield, true);
    return () => {
      window.removeEventListener("dragend", clearDragShield, true);
      window.removeEventListener("drop", clearDragShield, true);
    };
  }, []);

  async function runAction(actionKey: string, work: () => Promise<void>) {
    if (workspaceState?.readOnly && isDirtyAction(actionKey)) {
      setImportDialog({ status: "error", doneTitle: t("collaboration.readOnly"), message: t("collaboration.projectReadOnly") });
      return;
    }
    if (
      isDirtyAction(actionKey) &&
      workspaceState &&
      workspaceStateProjectPath !== currentProjectPath
    ) {
      void logDevEvent("error", "Mutation refusée : la leçon chargée ne correspond pas au chemin actif", {
        actionKey,
        activeProjectPath: currentProjectPath,
        loadedProjectPath: workspaceStateProjectPath,
        projectId: workspaceState.project.id
      });
      setImportDialog({
        status: "error",
        doneTitle: t("common.operationImpossible", undefined, "Opération impossible"),
        message: t(
          "lesson.projectBindingMismatch",
          undefined,
          "La leçon active est en cours de rechargement. Réessayez dans un instant."
        )
      });
      return;
    }
    setBusyAction(actionKey);
    void logDevEvent("info", "Action utilisateur démarrée", {
      actionKey,
      projectPath: currentProjectPath,
      projectId: workspaceState?.project.id ?? null
    });
    try {
      await work();
      if (isDirtyAction(actionKey)) {
        markProjectDirty();
      }
      void logDevEvent("info", "Action utilisateur terminée", {
        actionKey,
        projectPath: currentProjectPath,
        projectId: workspaceState?.project.id ?? null
      });
    } catch (error) {
      void logDevEvent("error", "Action utilisateur en échec", {
        actionKey,
        projectPath: currentProjectPath,
        projectId: workspaceState?.project.id ?? null,
        error: error instanceof Error ? error.message : String(error),
        stack: error instanceof Error ? error.stack : null
      });
      throw error;
    } finally {
      setBusyAction(null);
    }
  }

  async function runProjectLoading(work: () => Promise<void>) {
    setImportDialog({ status: "running", title: t("import.openingLesson") });
    await waitForNextPaint();
    try {
      await work();
      setLessonOpeningFontsPending(true);
      setImportDialog(null);
    } catch (error) {
      setLessonOpeningFontsPending(false);
      setImportDialog({
        status: "error",
        doneTitle: t("import.openingInterrupted"),
        message: error instanceof Error ? error.message : typeof error === "string" ? error : t("import.openingError")
      });
      throw error;
    }
  }

  function rememberRecentLesson(path: string) {
    if (!path || path === getDefaultProjectPath() || path.toLocaleLowerCase("en-US").endsWith(".paideia")) {
      return;
    }
    setRecentLessonPaths((current) => {
      const next = normalizeRecentLessonPaths([path, ...current]);
      localStorage.setItem(RECENT_LESSONS_KEY, JSON.stringify(next));
      return next;
    });
  }

  async function handleCreateModule() {
    await runAction("create-module", async () => {
      const nextState = await createModule({ projectPath: currentProjectPath, title: moduleDraft });
      setWorkspaceState(nextState);
    });
  }

  async function handleCreateChapter() {
    const targetModule = activeModule ?? project?.course.modules[0] ?? null;
    if (!targetModule) {
      await handleCreateModule();
      return;
    }

    await runAction("create-chapter", async () => {
      const nextState = await createChapter({
        projectPath: currentProjectPath,
        moduleId: targetModule.id,
        title: chapterDraft.trim() || t("lesson.newChapter")
      });
      setWorkspaceState(nextState);
      setChapterDraft("");
    });
  }

  async function handleUpdateProjectMetadata(
    nextTitle: string,
    nextAuthor: string,
    nextTitleStyle = courseTitleStyle,
    nextCourseCoverTitleHtml = project?.courseCoverTitleHtml ?? "",
    nextCourseIntroHtml = project?.courseIntroHtml ?? "",
    nextActivitySpacingPx = project?.activitySpacingPx ?? DEFAULT_LESSON_ACTIVITY_SPACING,
    nextCourseCoverStyle = project?.courseCoverStyle ?? DEFAULT_COURSE_COVER_STYLE,
    nextCourseImageRef = project?.courseImageRef ?? null
  ) {
    const normalizedTitle = normalizeProjectTitle(nextTitle);
    const rawAuthor = nextAuthor.trim();
    const normalizedAuthor = ["system", "système", "local-user"].includes(rawAuthor.toLocaleLowerCase("fr-FR"))
      ? ""
      : rawAuthor;
    const normalizedStyle = { ...DEFAULT_COURSE_TITLE_STYLE, ...nextTitleStyle };
    const currentStyle = { ...DEFAULT_COURSE_TITLE_STYLE, ...(project?.titleStyle ?? {}) };
    const normalizedCourseCoverTitleHtml = normalizeCourseCoverTitleHtml(nextCourseCoverTitleHtml, normalizedTitle);
    const currentCourseCoverTitleHtml = normalizeCourseCoverTitleHtml(project?.courseCoverTitleHtml ?? "", project?.title ?? normalizedTitle);
    const normalizedCourseIntroHtml = normalizeCourseIntroHtml(nextCourseIntroHtml);
    const currentCourseIntroHtml = normalizeCourseIntroHtml(project?.courseIntroHtml ?? "");
    const normalizedActivitySpacingPx = clampLessonActivitySpacing(nextActivitySpacingPx);
    const currentActivitySpacingPx = clampLessonActivitySpacing(project?.activitySpacingPx);
    const normalizedCourseCoverStyle = normalizeCourseCoverStyle(nextCourseCoverStyle);
    const currentCourseCoverStyle = normalizeCourseCoverStyle(project?.courseCoverStyle);
    if (
      !project ||
      (
        project.title === normalizedTitle &&
        visibleProjectAuthor(project) === normalizedAuthor &&
        JSON.stringify(currentStyle) === JSON.stringify(normalizedStyle) &&
        JSON.stringify(currentCourseCoverStyle) === JSON.stringify(normalizedCourseCoverStyle) &&
        normalizeHtmlForInlineCompare(resolveCourseCoverTitleHtml(currentCourseCoverTitleHtml, project.title)) === normalizeHtmlForInlineCompare(resolveCourseCoverTitleHtml(normalizedCourseCoverTitleHtml, normalizedTitle)) &&
        normalizeHtmlForInlineCompare(currentCourseIntroHtml) === normalizeHtmlForInlineCompare(normalizedCourseIntroHtml) &&
        currentActivitySpacingPx === normalizedActivitySpacingPx
      )
    ) {
      return;
    }

    await runAction("update-project-metadata", async () => {
      const previousPath = currentProjectPath;
      const result = await updateProjectMetadata({
        projectPath: currentProjectPath,
        title: normalizedTitle,
        author: normalizedAuthor,
        courseImageRef: nextCourseImageRef,
        courseCoverTitleHtml: normalizedCourseCoverTitleHtml,
        titleStyle: normalizedStyle,
        courseIntroHtml: normalizedCourseIntroHtml,
        courseCoverStyle: normalizedCourseCoverStyle,
        activitySpacingPx: normalizedActivitySpacingPx
      });
      setWorkspaceState(result.workspaceState);
      if (result.projectPath !== previousPath) {
        remapProjectPath(previousPath, result.projectPath, result.workspaceState.project.title);
      }
      upsertProjectTab(result.projectPath, result.workspaceState.project.title);
    });
  }

  async function handleCommitLessonActivitySpacing(nextSpacing: number) {
    if (!project) {
      return;
    }

    const normalizedSpacing = clampLessonActivitySpacing(nextSpacing);
    setLessonActivitySpacingDraft(normalizedSpacing);

    if (clampLessonActivitySpacing(project.activitySpacingPx) === normalizedSpacing) {
      return;
    }

    await runAction("update-project-activity-spacing", async () => {
      const previousPath = currentProjectPath;
      const result = await updateProjectMetadata({
        projectPath: currentProjectPath,
        title: project.title,
        author: visibleProjectAuthor(project),
        courseImageRef: project.courseImageRef ?? null,
        courseCoverTitleHtml: project.courseCoverTitleHtml ?? "",
        titleStyle: { ...DEFAULT_COURSE_TITLE_STYLE, ...(project.titleStyle ?? {}) },
        customFont: project.customFont ?? null,
        courseIntroHtml: project.courseIntroHtml ?? "",
        courseCoverStyle: normalizeCourseCoverStyle(project.courseCoverStyle),
        activitySpacingPx: normalizedSpacing
      });
      setWorkspaceState(result.workspaceState);
      if (result.projectPath !== previousPath) {
        remapProjectPath(previousPath, result.projectPath, result.workspaceState.project.title);
      }
      upsertProjectTab(result.projectPath, result.workspaceState.project.title);
    });
  }

  async function handleCommitCourseAppearance(patch: Partial<CourseAppearance>) {
    if (!project) {
      return;
    }

    const nextAppearance = normalizeCourseAppearance({
      ...normalizeCourseAppearance(project.courseAppearance),
      ...patch
    });
    if (JSON.stringify(nextAppearance) === JSON.stringify(normalizeCourseAppearance(project.courseAppearance))) {
      return;
    }

    await runAction("update-project-course-appearance", async () => {
      const result = await updateProjectMetadata({
        projectPath: currentProjectPath,
        title: project.title,
        author: visibleProjectAuthor(project),
        courseImageRef: project.courseImageRef ?? null,
        courseCoverTitleHtml: project.courseCoverTitleHtml ?? "",
        titleStyle: { ...DEFAULT_COURSE_TITLE_STYLE, ...(project.titleStyle ?? {}) },
        customFont: project.customFont ?? null,
        courseIntroHtml: project.courseIntroHtml ?? "",
        courseCoverStyle: normalizeCourseCoverStyle(project.courseCoverStyle),
        activitySpacingPx: clampLessonActivitySpacing(project.activitySpacingPx),
        courseAppearance: nextAppearance
      });
      setWorkspaceState(result.workspaceState);
    });
  }

