  useEffect(() => {
    if (!isLibraryRootReady || !isTauriRuntimeAvailable()) {
      return;
    }
    void listUserFonts(importDestinationRoot).then(setUserFonts).catch(() => setUserFonts([]));
  }, [importDestinationRoot, isLibraryRootReady]);

  const projectFontsRequestRef = useRef<{ path: string; promise: Promise<LessonCustomFont[]> } | null>(null);
  useEffect(() => {
    if (!currentProjectPath || !isTauriRuntimeAvailable()) {
      setProjectRichTextFonts([]);
      setProjectRichTextFontsLoadedPath(currentProjectPath || "");
      return;
    }
    if (projectRichTextFontsLoadedPath === currentProjectPath) return;
    let cancelled = false;
    setProjectRichTextFontsLoadedPath("");
    let request = projectFontsRequestRef.current;
    if (request?.path !== currentProjectPath) {
      request = { path: currentProjectPath, promise: listProjectRichTextFonts(currentProjectPath) };
      projectFontsRequestRef.current = request;
    }
    const pending = request;
    void pending.promise.then((fonts) => {
      if (cancelled) return;
      setProjectRichTextFonts(fonts);
      setProjectRichTextFontsLoadedPath(currentProjectPath);
    }).catch(() => {
      if (cancelled) return;
      setProjectRichTextFonts([]);
      setProjectRichTextFontsLoadedPath(currentProjectPath);
    }).finally(() => {
      if (projectFontsRequestRef.current === pending) projectFontsRequestRef.current = null;
    });
    return () => { cancelled = true; };
  }, [currentProjectPath, project?.customFont?.assetRef, project?.customFont?.id, project?.id]);

  useEffect(() => {
    if (!project || !currentProjectPath || projectRichTextFontsLoadedPath !== currentProjectPath) {
      return;
    }
    let cancelled = false;
    void waitForProjectRichTextFonts(currentProjectPath, project, projectRichTextFonts).then(() => {
      if (!cancelled) setLessonFontsReadyKey(lessonFontReadyKey);
    });
    return () => {
      cancelled = true;
    };
  }, [currentProjectPath, lessonFontReadyKey, project, projectRichTextFonts, projectRichTextFontsLoadedPath]);

  async function handleUploadProjectFont(file: File | null) {
    if (!file) {
      return;
    }

    setFontOperationError(null);
    try {
      await runAction("project-font-import", async () => {
        const nextState = await uploadProjectFont(currentProjectPath, file);
        setProjectRichTextFonts(await listProjectRichTextFonts(currentProjectPath));
        setWorkspaceState(nextState);
      });
    } catch (error) {
      setFontOperationError(error instanceof Error ? error.message : String(error));
    } finally {
      if (projectFontInputRef.current) {
        projectFontInputRef.current.value = "";
      }
    }
  }

