  async function handleSaveReferenceBankResources(bankId: string) {
    if (referenceBankSaveJob.current) return referenceBankSaveJob.current;
    const job = saveReferenceBankResources(bankId);
    referenceBankSaveJob.current = job;
    try { await job; }
    finally { referenceBankSaveJob.current = null; }
  }

  async function saveReferenceBankResources(bankId: string) {
    setResourceReferenceSaveFeedbackState("saving");
    try {
      await runAction("save-user-reference-banks", async () => {
        await flushActiveInlineRichTextCommit();
        const previousBanks = await listUserReferenceBanks();
        const currentDrafts = userReferenceBanksRef.current;
        const selectedDraft = currentDrafts.find((bank) => bank.id === bankId);
        if (!selectedDraft) await deleteUserReferenceBank(bankId);
        const savedBanks = await saveUserReferenceBanks([
          ...previousBanks.filter((bank) => bank.id !== bankId),
          ...(selectedDraft ? [selectedDraft] : [])
        ], []);
        const savedSelected = savedBanks.find((bank) => bank.id === bankId);
        const nextDrafts = currentDrafts.filter((bank) => bank.id !== bankId);
        if (savedSelected) nextDrafts.push(savedSelected);
        userReferenceBanksRef.current = nextDrafts;
        setUserReferenceBanks(nextDrafts);
        const failures: string[] = [];
        const affectedPaths = new Set([...previousBanks, ...savedBanks]
          .filter((bank) => bank.id === bankId)
          .flatMap((bank) => bank.projectPaths));
        for (const entry of libraryProjectsWithCollections.filter((entry) => affectedPaths.has(entry.archivePath))) {
          try {
            await applyUserReferenceBanks(entry.archivePath, entry.archivePath);
            const session = openLessonSessions.get(entry.archivePath);
            if (session || currentProjectPath === entry.archivePath) {
              const refreshed = await loadWorkspaceStateForProject(entry.archivePath);
              if (session) openLessonSessions.remember(entry.archivePath, { ...session, workspaceState: refreshed });
              if (currentProjectPath === entry.archivePath && workspaceStateProjectPath === entry.archivePath) {
                setWorkspaceState(refreshed);
              }
            }
          } catch (cause) {
            failures.push(`${entry.title} : ${cause instanceof Error ? cause.message : String(cause)}`);
          }
        }
        if (failures.length) throw new Error(`Banque enregistrée localement. Certaines leçons n’ont pas été mises à jour :\n${failures.join("\n")}`);
      });
      setResourceReferenceSaveFeedbackState("saved");
      window.setTimeout(() => setResourceReferenceSaveFeedbackState("idle"), 1800);
    } catch (error) {
      setResourceReferenceSaveFeedbackState("error");
      throw error;
    }
  }

  async function handleSaveGlossaryAssistantResources(bankIds?: string[], metadataOnlyIds: string[] = []) {
    if (resourceAssistantSaveFeedbackTimeoutRef.current !== null) {
      window.clearTimeout(resourceAssistantSaveFeedbackTimeoutRef.current);
      resourceAssistantSaveFeedbackTimeoutRef.current = null;
    }

    setResourceAssistantSaveFeedbackState("saving");
    try {
    await runAction("save-user-glossary-assistants", async () => {
      const projectPathsToSync = libraryProjectsWithCollections.map((entry) => entry.archivePath);
      const claimedProjectPaths = new Set<string>();
      const normalizedAssistants = userGlossaryAssistantsRef.current.map((assistant) => {
        const projectPaths = (assistant.projectPaths ?? []).filter((projectPath) => {
          if (claimedProjectPaths.has(projectPath)) {
            return false;
          }
          claimedProjectPaths.add(projectPath);
          return true;
        });
        return { ...assistant, projectPaths };
      });
      const drafts = userGlossaryAssistantsRef.current;
      const toSave = normalizedAssistants.filter(assistant => !bankIds || bankIds.includes(assistant.id)
        || JSON.stringify(assistant.projectPaths) !== JSON.stringify(drafts.find(bank => bank.id === assistant.id)?.projectPaths));
      const saved = await saveUserGlossaryAssistants(toSave.map(bank => metadataOnlyIds.includes(bank.id)
        ? { ...bank, contentLoaded: false, entries: [], fallbackResponses: [] } : bank), projectPathsToSync);
      const savedAssistants = drafts.map(bank => {
        const result = saved.find(item => item.id === bank.id);
        if (!result) return bank;
        return metadataOnlyIds.includes(bank.id)
          ? { ...result, entries: bank.entries, fallbackResponses: bank.fallbackResponses, contentLoaded: bank.contentLoaded, contentCount: bank.contentCount } : result;
      });
      userGlossaryAssistantsRef.current = savedAssistants;
      setUserGlossaryAssistants(savedAssistants);
      const currentProjectAssistants = (await Promise.all(savedAssistants
        .filter((assistant) => (assistant.projectPaths ?? []).includes(currentProjectPath))
        .map(assistant => loadResourceBank("assistants", assistant))))
        .map((assistant) => ({
          ...assistant,
          assistantEnabled: true,
          projectPaths: [],
          collectionIds: [],
          lessonIds: []
        }));
      setWorkspaceState((current) =>
        current
          ? {
              ...current,
              project: {
                ...current.project,
                glossaryAssistants: currentProjectAssistants
              }
            }
          : current
      );
    });
      setResourceAssistantSaveFeedbackState("saved");
      resourceAssistantSaveFeedbackTimeoutRef.current = window.setTimeout(() => {
        setResourceAssistantSaveFeedbackState("idle");
        resourceAssistantSaveFeedbackTimeoutRef.current = null;
      }, 1800);
    } catch (error) {
      setResourceAssistantSaveFeedbackState("error");
      throw error;
    }
  }

