  function userCharacterPreviewUrl(character: DefaultSituationalDialogueCharacterDefinition) {
    if ("previewRef" in character && typeof character.previewRef === "string" && character.previewRef && userSituationalDialogueCharacterBankPath) {
      return buildLibraryImageUrl(`${userSituationalDialogueCharacterBankPath.replace(/[\\\/]+$/, "")}/${character.previewRef}`);
    }
    const pose =
      character.poses.find((candidate) => candidate.state === "positive") ??
      character.poses.find((candidate) => candidate.state === "neutral") ??
      character.poses[0];
    if (!pose || !userSituationalDialogueCharacterBankPath) {
      return null;
    }
    return buildLibraryImageUrl(`${userSituationalDialogueCharacterBankPath.replace(/[\\\/]+$/, "")}/${pose.assetRef}`);
  }

