  function showPaideiaArchiveImportError(error: unknown) {
    const backendMessage = error instanceof Error
      ? error.message.trim()
      : typeof error === "string"
        ? error.trim()
        : "";
    const lines = backendMessage.split(/\r?\n/u);
    if (backendMessage.includes("Veuillez mettre à jour PAIDEIA.")) {
      setImportDialog({ status: "error", doneTitle: t("paideia.updateRequired"), message: backendMessage });
      return;
    }
    const isSecurityRejection = lines[0] === "PAIDEIA_SECURITY_ARCHIVE_REJECTED";
    const isIntegrityRejection =
      lines.includes("PAIDEIA_ARCHIVE_INTEGRITY_REJECTED") ||
      /Contrôle d’intégrité SHA-256 en échec/u.test(backendMessage) ||
      /ne contient pas de manifeste d’intégrité/u.test(backendMessage) ||
      /Le manifeste d’intégrité PAIDEIA (?:est illisible|n’est pas pris en charge|ne correspond pas au contenu de l’archive|contient une entrée invalide)/u.test(backendMessage) ||
      /Fichier (?:absent du manifeste d’intégrité|déclaré mais absent de l’archive)/u.test(backendMessage);
    setImportDialog({
      status: "error",
      doneTitle: isSecurityRejection
        ? t("scorm.importSecurityRejected")
        : t("paideia.importArchiveTitle", undefined, "Importer une archive PAIDEIA"),
      message: isSecurityRejection
        ? lines.slice(1).join("\n")
        : isIntegrityRejection
          ? t(
              "paideia.importArchiveIntegrityFailed",
              undefined,
              "L’archive PAIDEIA n’a pas pu être importée car son contenu a été modifié depuis son exportation. Son intégrité ne peut donc pas être garantie."
            )
        : t("paideia.importArchiveFailed", undefined, "L’archive PAIDEIA n’a pas pu être importée.")
    });
  }

  useEffect(() => {
    if (!isLibraryRootReady || !importDestinationRoot) return;
    let disposed = false;
    let draining = false;
    let requested = false;
    async function drain() {
      requested = true;
      if (disposed || draining) return;
      draining = true;
      const handled = new Set<string>();
      try {
        while (requested && !disposed) {
          requested = false;
          while (!disposed) {
            const path = await getStartupPaideiaArchive();
            if (!path) break;
            const key = path.split("\\").join("/").toLowerCase();
            if (handled.has(key)) continue;
            handled.add(key);
            await handleImportPaideiaArchive(() => openPaideiaArchivePath(path, importDestinationRoot));
          }
        }
      } finally {
        draining = false;
      }
    }
    const subscription = listen("paideia-archive-pending", () => void drain());
    void subscription.then(() => drain(), () => drain());
    return () => {
      disposed = true;
      void subscription.then((unlisten) => unlisten(), () => {});
    };
  }, [importDestinationRoot, isLibraryRootReady]);

  function handleImportPaideiaArchive(importArchive: () => Promise<string>) {
    const task = archiveImportQueueRef.current.then(() => performPaideiaArchiveImport(importArchive));
    archiveImportQueueRef.current = task.catch(() => {});
    return task;
  }

  function chooseArchiveBanks(mode: "import" | "export" | "update", update?: SharedBankUpdate) {
    const choice = archiveBanksChoiceQueue.current.then(() =>
      new Promise<boolean | null>((resolve) => setArchiveBanksDialog({ mode, update, resolve }))
    );
    archiveBanksChoiceQueue.current = choice;
    return choice;
  }

  function closeArchiveBanksDialog(choice: boolean | null) {
    if (!archiveBanksDialog) return;
    setArchiveBanksDialog((current) => current === archiveBanksDialog ? null : current);
    archiveBanksDialog.resolve(choice);
  }

  async function performPaideiaArchiveImport(importArchive: () => Promise<string>) {
    setImportDialog({ status: "running" });
    try {
      const projectPath = await importArchive();
      await refreshLibraryProjects();
      try {
        if (await hasPaideiaSharedBanks(projectPath)) {
          setImportDialog(null);
          if (await chooseArchiveBanks("import")) {
            const choices: Record<string, string> = {};
            for (const update of await inspectPaideiaSharedBankUpdates(projectPath)) {
              if (await chooseArchiveBanks("update", update)) choices[update.key] = update.fingerprint;
            }
            setImportDialog({ status: "running" });
            await importPaideiaSharedBanks(projectPath, choices);
            await Promise.all([refreshUserQuestionBank(), refreshUserReferenceBank(), refreshUserGlossaryAssistantBank()]);
          }
        }
        setImportDialog({ status: "done" });
      } catch {
        setImportDialog({ status: "error", message: archiveText("paideia.sharedBanksImportFailed") });
      }
    } catch (error) {
      showPaideiaArchiveImportError(error);
    }
  }

  async function handleOpenPaideiaArchive(file: File) {
    await handleImportPaideiaArchive(() => openPaideiaArchive(file, importDestinationRoot));
  }

  async function handleOpenLessonPath(sourcePath: string, readOnly = false) {
    const isPaideiaArchive = sourcePath.toLowerCase().endsWith(".paideia");
    if (isPaideiaArchive) {
      await handleImportPaideiaArchive(() => openPaideiaArchivePath(sourcePath, importDestinationRoot));
      return;
    }
    try {
      await runProjectLoading(() => runAction("open-paideia", async () => {
      const openedProjectPath = sourcePath.toLowerCase().endsWith(".paideia")
        ? await openPaideiaArchivePath(sourcePath, importDestinationRoot)
        : sourcePath;
      const nextState = await loadLocalizedWorkspace(openedProjectPath, readOnly);
      setCurrentProjectPath(openedProjectPath);
      setWorkspaceStateProjectPath(openedProjectPath);
      setWorkspaceState(nextState);
      upsertProjectTab(
        openedProjectPath,
        nextState.project.title,
        sourcePath.toLowerCase().endsWith(".paideia") ? sourcePath : undefined
      );
      rememberRecentLesson(openedProjectPath);
      const firstPage = flattenPages(nextState.project)[0];
      setActivePageId(firstPage?.id ?? "");
      setSelectedBlockId(firstPage?.blocks[0]?.id ?? "");
      setIsInspectorOpen(false);
      showProjectWorkspace();
      setIsPreviewMode(Boolean(readOnly || nextState.readOnly));
      setCurrentArchivePath(sourcePath.toLowerCase().endsWith(".paideia") ? sourcePath : "");
      }));
    } catch (error) {
      if (isPaideiaArchive) {
        showPaideiaArchiveImportError(error);
        return;
      }
      throw error;
    }
  }

