        setActivePageId(firstPage?.id ?? "");
        setSelectedBlockId(firstPage?.blocks[0]?.id ?? "");
        setIsInspectorOpen(false);
        showProjectWorkspace();
        setCurrentArchivePath("");
        markProjectClean(projectPath);
