  async function handleExportLibraryCollectionScorm12(collection: string) {
    if (busyAction) {
      return;
    }

    const collectionName = collection.trim();
    setLibraryActionMenu(null);
    if (!collectionName) {
      return;
    }

    const collectionProjects = allLibraryProjects.filter(
      (entry) => entry.collection === collectionName
    );
    if (!collectionProjects.length) {
      setScormBatchSummary({
        title: t("scorm.noLessonToExport"),
        collection: collectionName,
        exportedCount: 0,
        totalCount: 0,
        errors: []
      });
      return;
    }

    const shouldExport = window.confirm(t(
      "scorm.confirmCollectionExport",
      {
        collection: collectionName,
        count: collectionProjects.length,
        lessonCount: t(collectionProjects.length === 1 ? "scorm.oneLessonWillExport" : "scorm.lessonsWillExport", { count: collectionProjects.length })
      }
    ));
    if (!shouldExport) {
      return;
    }

    const selectedDirectory = await openDialog({
      directory: true,
      multiple: false,
      title: t("scorm.chooseExportFolder", undefined, "Choisir le dossier d'export SCORM 1.2")
    });
    const destinationRoot = Array.isArray(selectedDirectory) ? selectedDirectory[0] : selectedDirectory;
    if (!destinationRoot) {
      return;
    }

    await runAction("export-library-collection-scorm", async () => {
      const usedNames = new Set<string>();
      const errors: string[] = [];
      let exportedCount = 0;
      try {
        for (const [index, entry] of collectionProjects.entries()) {
          setScormBatchProgress({
            collection: collectionName,
            current: index + 1,
            total: collectionProjects.length,
            lessonTitle: entry.title
          });

          try {
            const archivePath = await scormBatchArchivePath(destinationRoot, entry.title, usedNames);
            await exportScorm12To(entry.archivePath, archivePath, appLanguage);
            exportedCount += 1;
          } catch (error) {
            errors.push(`${entry.title} : ${error instanceof Error ? error.message : String(error)}`);
          }
        }
      } finally {
        setScormBatchProgress(null);
      }

      setScormBatchSummary({
        title: t("scorm.exportComplete"),
        collection: collectionName,
        exportedCount,
        totalCount: collectionProjects.length,
        errors,
        destinationRoot
      });
    });
  }

