  async function saveLearnerResourcePdf(fileName: string, fileBytes: number[]) {
    const safeFileName = fileName.replace(/[/\\?%*:|"<>]/g, "-").trim() || "ressource-apprenant.pdf";
    const targetPath = await save({
      defaultPath: `${importDestinationRoot.replace(/\\/g, "/")}/archives/${safeFileName}`,
      filters: [{ name: "Document PDF", extensions: ["pdf"] }]
    });
    if (!targetPath) return;
    let binary = "";
    for (let index = 0; index < fileBytes.length; index += 0x8000) {
      binary += String.fromCharCode(...fileBytes.slice(index, index + 0x8000));
    }
    await writePdfExportAtomic(targetPath, btoa(binary));
  }

  async function flushActiveInlineRichTextCommit() {
    const editor = richEditorRef.current;
    if (editor?.dataset.inlineRichEditor === "true") {
      editor.blur();
      // InlineRichTextField deliberately validates blur after focus has settled.
      // Wait for that macrotask before reading the serialized commit chain.
      await new Promise<void>((resolve) => window.setTimeout(resolve, 0));
    }
    await inlineRichTextCommitRef.current;
  }

  function beginStructuralInlineRichTextFlush(source: string) {
    const activeBlockId = inlineRichTextSessionRef.current?.blockId ?? null;
    const pendingFlush = flushActiveInlineRichTextCommit().then(() => {
      setInlineRichTextSession(null);
    });
    structuralInlineRichTextFlushRef.current = pendingFlush;
    void pendingFlush.catch((error) => {
      void logDevEvent("error", "Pré-enregistrement RichText avant mutation en échec", {
        source,
        blockId: activeBlockId,
        error: error instanceof Error ? error.message : String(error)
      });
    });
  }

  async function secureInlineRichTextBeforeStructuralMutation() {
    const primedFlush = structuralInlineRichTextFlushRef.current;
    try {
      await primedFlush;
    } finally {
      if (structuralInlineRichTextFlushRef.current === primedFlush) {
        structuralInlineRichTextFlushRef.current = Promise.resolve();
      }
    }
    await flushActiveInlineRichTextCommit();
    setInlineRichTextSession(null);
  }

  async function flushPendingLessonEdits() {
    await flushActiveInlineRichTextCommit();
    const formChanged = initialBlockFormRef.current !== null
      && JSON.stringify(blockFormRef.current) !== JSON.stringify(initialBlockFormRef.current);
    const hasPendingMedia = pendingBlockMediaDraftRef.current?.blockId === selectedBlock?.id;
    if (
      isProjectWorkspaceActive &&
      !isPreviewMode &&
      isInspectorOpen &&
      selectedBlock &&
      workspaceStateProjectPath === currentProjectPath &&
      (formChanged || hasPendingMedia)
    ) {
      await latestHandleSaveBlockRef.current?.({ closeInspector: false });
    }
  }

  async function canCloseProjectTab(tab: ProjectTab) {
    if (tab.path === currentProjectPath) {
      await flushPendingLessonEdits();
    }
    markProjectClean(tab.path);
    return true;
  }

  async function closeProjectTabNow(tab: ProjectTab) {
    openLessonSessions.forget(tab.path);
    const nextTabs = projectTabsRef.current.filter((item) => item.path !== tab.path);
    projectTabsRef.current = nextTabs;
    setProjectTabs(nextTabs);
    if (tab.path !== currentProjectPath) {
      return;
    }
    setCurrentArchivePath("");
    showProjectLibraryScreen();
  }

  async function handleSwitchProjectTab(tab: ProjectTab) {
    if (tab.path === currentProjectPath && isProjectWorkspaceActive) {
      rememberRecentLesson(tab.path);
      showProjectWorkspace();
      setIsPreviewMode(Boolean(workspaceState?.readOnly));
      return;
    }

    if (currentProjectPath && tab.path !== currentProjectPath) {
      await flushPendingLessonEdits();
    }

    if (
      workspaceState &&
      currentProjectPath &&
      workspaceStateProjectPath === currentProjectPath &&
      projectTabs.some((entry) => entry.path === currentProjectPath)
    ) {
      openLessonSessions.remember(currentProjectPath, {
        projectPath: currentProjectPath,
        workspaceState,
        activePageId,
        selectedBlockId,
        archivePath: currentArchivePath,
        isPreviewMode,
        isLessonMenuOpen,
        previewCompletedBlocks,
        previewQuizResults,
        projectRichTextFonts,
        lessonFontsReadyKey
      });
    }

    const cachedSession = openLessonSessions.get(tab.path);
    if (cachedSession) {
      setCurrentProjectPath(tab.path);
      setWorkspaceStateProjectPath(tab.path);
      setWorkspaceState(cachedSession.workspaceState);
      setCurrentArchivePath(cachedSession.archivePath || tab.archivePath || "");
      setActivePageId(cachedSession.activePageId);
      setSelectedBlockId(cachedSession.selectedBlockId);
      setPreviewCompletedBlocks(cachedSession.previewCompletedBlocks);
      setPreviewQuizResults(cachedSession.previewQuizResults);
      setProjectRichTextFonts(cachedSession.projectRichTextFonts);
      setProjectRichTextFontsLoadedPath(tab.path);
      setLessonFontsReadyKey(cachedSession.lessonFontsReadyKey);
      setLessonOpeningFontsPending(false);
      rememberRecentLesson(tab.path);
      upsertProjectTab(tab.path, cachedSession.workspaceState.project.title, tab.archivePath);
      showProjectWorkspace();
      setIsLessonMenuOpen(cachedSession.isLessonMenuOpen);
      setIsPreviewMode(cachedSession.isPreviewMode || Boolean(cachedSession.workspaceState.readOnly));
      return;
    }

    await runProjectLoading(() => runAction("switch-project-tab", async () => {
      const nextState = await loadLocalizedWorkspace(tab.path);
      setCurrentProjectPath(tab.path);
      setWorkspaceStateProjectPath(tab.path);
      setWorkspaceState(nextState);
      upsertProjectTab(tab.path, nextState.project.title);
      rememberRecentLesson(tab.path);
      setCurrentArchivePath(tab.archivePath ?? "");
      const firstPage = flattenPages(nextState.project)[0];
      setActivePageId(firstPage?.id ?? "");
      setSelectedBlockId(firstPage?.blocks[0]?.id ?? "");
      setIsInspectorOpen(false);
      showProjectWorkspace();
      setIsPreviewMode(Boolean(nextState.readOnly));
    }));
  }

  async function handleCloseProjectTab(tab: ProjectTab) {
    if (!(await canCloseProjectTab(tab))) {
      return;
    }
    await closeProjectTabNow(tab);

  }

  async function closeApplicationWithPrompts() {
    if (closeFlowInProgressRef.current) {
      return false;
    }

    closeFlowInProgressRef.current = true;
    // Finish the local save and persist its pending flags before allowing exit.
    await referenceBankSaveJob.current?.catch(() => undefined);
    try { await flushPendingLessonEdits(); }
    catch (error) {
      closeFlowInProgressRef.current = false;
      setImportDialog({ status: "error", doneTitle: t("collaboration.syncPending"), message: String(error) });
      return false;
    }
    for (const tab of projectTabs) markProjectClean(tab.path);
    openLessonSessions.clear();
    setProjectTabs([]);
    closeRequestedByAppRef.current = true;
    try {
      await quitPaideia();
    } catch {
      await getCurrentWindow().destroy();
    }
    return true;
  }

  useEffect(() => {
    if (!isTauri()) {
      return;
    }

    let disposed = false;
    let unlisten: (() => void) | null = null;
    void getCurrentWindow().onCloseRequested(async (event) => {
      if (closeRequestedByAppRef.current) {
        return;
      }
      event.preventDefault();
      if (disposed || closeFlowInProgressRef.current) {
        return;
      }
      await closeApplicationWithPrompts();
    }).then((cleanup) => {
      unlisten = cleanup;
    });

    return () => {
      disposed = true;
      unlisten?.();
    };
  }, [projectTabs, dirtyProjectPaths, currentProjectPath, currentArchivePath, workspaceState, importDestinationRoot, busyAction]);

