  async function commitTimelineInlineText(
    blockId: string,
    itemId: string,
    field: TimelineInlineField,
    html: string
  ) {
    const context = findBlockContext(blockId);
    if (!context || !currentProjectPath || currentProjectPath === getDefaultProjectPath()) {
      return;
    }

    const currentItem = (context.block.activityItems ?? []).find((item) => item.id === itemId);
    if (!currentItem) {
      return;
    }

    const normalizedHtml = normalizeTimelineInlineValue(field, html);
    const currentHtml = (currentItem[field] as string | null | undefined)?.trim() || timelineFieldFallback(field);
    if (normalizeHtmlForInlineCompare(normalizedHtml) === normalizeHtmlForInlineCompare(currentHtml)) {
      return;
    }

    const nextItems = (context.block.activityItems ?? []).map((item) =>
      item.id === itemId
        ? {
            ...item,
            [field]: normalizedHtml
          }
        : item
    );
    const nextState = await persistBlockActivityItems(context, nextItems);
    if (nextState) {
      await saveCommittedInlineSnapshot(
        currentProjectPath,
        context.block.title || localizedActivityLabel(context.block.type),
        nextState.project.currentVersion ?? "autosave"
      );
    }

    const updatedSession = inlineRichTextSessionRef.current;
    if (updatedSession?.blockId === blockId && updatedSession.itemId === itemId && updatedSession.itemField === field) {
      setInlineRichTextSession({
        ...updatedSession,
        lastSavedHtml: normalizedHtml
      });
    }
  }

