  function image360HotspotInlineHasMeaningfulHtml(value: string | null | undefined) {
    if (!value) {
      return false;
    }
    if (/<img\b/i.test(value)) {
      return true;
    }
    return Boolean(stripHtmlForEditor(value).replace(/\s+/g, " ").trim());
  }

  function normalizeImage360HotspotInlineValue(field: Image360HotspotInlineField, html: string) {
    const fallback = image360HotspotInlineFieldFallback(field);
    const normalized = normalizeFrenchTypographyInHtml(html?.trim() || fallback);
    return image360HotspotInlineHasMeaningfulHtml(normalized) ? normalized : "";
  }

  function handleImage360HotspotInlineTextActivate(
    editor: HTMLDivElement,
    block: PaideiaBlock,
    hotspotId: string,
    field: Image360HotspotInlineField,
    html: string,
    profile: RichTextToolbarProfile
  ) {
    richEditorRef.current = editor;
    const currentSession = inlineRichTextSessionRef.current;
    const sessionKey = richToolbarSessionKey(block.id, hotspotId, field);
    const isNewSession =
      !currentSession ||
      currentSession.blockId !== block.id ||
      currentSession.itemId !== hotspotId ||
      currentSession.itemField !== field;
    if (isNewSession) {
      const initialHtml = html?.trim() || image360HotspotInlineFieldFallback(field);
      initializeRichToolbarColorForSession(editor, sessionKey);
      setInlineRichTextSession({
        blockId: block.id,
        itemId: hotspotId,
        itemField: field,
        profile,
        originalHtml: initialHtml,
        currentHtml: initialHtml,
        lastSavedHtml: initialHtml,
        snapshotCreated: false
      });
    } else {
      refreshPendingRichToolbarColorForSession(editor, sessionKey);
    }
    saveRealRichEditorSelection();
  }

  function handleImage360HotspotInlineTextCommit(
    blockId: string,
    hotspotId: string,
    field: Image360HotspotInlineField,
    html: string,
    commitHtml: (html: string) => void
  ) {
    const normalizedHtml = normalizeImage360HotspotInlineValue(field, html);
    const session = inlineRichTextSessionRef.current;
    const previousHtml =
      session?.blockId === blockId && session.itemId === hotspotId && session.itemField === field
        ? session.lastSavedHtml
        : "";

    if (normalizeHtmlForInlineCompare(previousHtml) !== normalizeHtmlForInlineCompare(normalizedHtml)) {
      commitHtml(normalizedHtml);
    }

    const updatedSession = inlineRichTextSessionRef.current;
    if (updatedSession?.blockId === blockId && updatedSession.itemId === hotspotId && updatedSession.itemField === field) {
      setInlineRichTextSession({
        ...updatedSession,
        currentHtml: normalizedHtml,
        lastSavedHtml: normalizedHtml
      });
    }

    window.setTimeout(() => {
      const activeElement = document.activeElement;
      if (activeElement instanceof HTMLElement && activeElement.closest(".inline-rich-text-wrapper")) {
        return;
      }
      setInlineRichTextSession(null);
    }, 0);
  }

