  function tabsEditorFieldFallback(field: TabsRichTextFieldName) {
    return field === "contentHtml" ? "<p></p>" : "";
  }

  function tabsEditorFieldHasMeaningfulHtml(value: string | null | undefined) {
    if (!value) {
      return false;
    }
    if (/<(?:img|table)\b/i.test(value)) {
      return true;
    }
    return Boolean(stripHtmlForEditor(value).replace(/\s+/g, " ").trim());
  }

  function normalizeTabsEditorFieldValue(field: TabsRichTextFieldName, html: string) {
    const fallback = tabsEditorFieldFallback(field);
    const normalized = normalizeFrenchTypographyInHtml(html?.trim() || fallback);
    return tabsEditorFieldHasMeaningfulHtml(normalized) ? normalized : "";
  }

  function handleTabsEditorRichTextActivate(
    editor: HTMLDivElement,
    block: PaideiaBlock,
    item: ActivityItem,
    field: TabsRichTextFieldName,
    html: string,
    profile: RichTextToolbarProfile
  ) {
    richEditorRef.current = editor;
    const currentSession = inlineRichTextSessionRef.current;
    const sessionKey = richToolbarSessionKey(block.id, item.id, field);
    const isNewSession =
      !currentSession ||
      currentSession.blockId !== block.id ||
      currentSession.itemId !== item.id ||
      currentSession.itemField !== field;
    if (isNewSession) {
      const initialHtml = html?.trim() || tabsEditorFieldFallback(field);
      const currentValue = initialHtml;
      initializeRichToolbarColorForSession(editor, sessionKey);
      setInlineRichTextSession({
        blockId: block.id,
        itemId: item.id,
        itemField: field,
        profile,
        originalHtml: initialHtml,
        currentHtml: currentValue,
        lastSavedHtml: currentValue,
        snapshotCreated: false
      });
    } else {
      refreshPendingRichToolbarColorForSession(editor, sessionKey);
    }
    saveRealRichEditorSelection();
  }

  function handleTabsEditorRichTextCommit(
    blockId: string,
    itemId: string,
    field: TabsRichTextFieldName,
    html: string
  ) {
    if (!isCurrentBlockForm(blockId)) return;
    const normalizedHtml = normalizeTabsEditorFieldValue(field, html);

    setBlockForm((current) => {
      const currentItem = current.activityItems.find((item) => item.id === itemId);
      const currentHtml = (currentItem?.[field] as string | null | undefined)?.trim() || "";
      if (normalizeHtmlForInlineCompare(normalizedHtml) === normalizeHtmlForInlineCompare(currentHtml)) {
        return current;
      }
      return {
        ...current,
        activityItems: current.activityItems.map((item) =>
          item.id === itemId
            ? {
                ...item,
                [field]: normalizedHtml
              }
            : item
        )
      };
    });

    const updatedSession = inlineRichTextSessionRef.current;
    if (updatedSession?.blockId === blockId && updatedSession.itemId === itemId && updatedSession.itemField === field) {
      setInlineRichTextSession({
        ...updatedSession,
        currentHtml: normalizedHtml,
        lastSavedHtml: normalizedHtml
      });
    }

    window.setTimeout(() => {
      const activeElement = document.activeElement;
      if (activeElement instanceof HTMLElement && activeElement.closest(".inline-rich-text-wrapper")) {
        return;
      }
      setInlineRichTextSession(null);
    }, 0);
  }

  function commitPanelInlineText(blockId: string, itemId: string, field: TabsRichTextFieldName, html: string) {
    const projectPath = currentProjectPath;
    const normalizedHtml = normalizeTabsEditorFieldValue(field, html);
    // Serialize saves and read the latest items, including the preceding save,
    // so quick edits across tabs or accordion panels preserve every composition.
    const pendingCommit = inlineRichTextCommitRef.current.then(async () => {
      const latest = panelInlineWorkspaceRef.current;
      if (!latest.workspaceState || latest.projectPath !== projectPath || projectPath === getDefaultProjectPath()) return;
      const page = flattenPages(latest.workspaceState.project).find((candidate) => candidate.blocks.some((block) => block.id === blockId));
      const block = page?.blocks.find((candidate) => candidate.id === blockId);
      const item = block?.activityItems?.find((candidate) => candidate.id === itemId);
      if (!page || !block || !["tabs", "accordion"].includes(block.type) || !item) return;
      const mergeLegacyTitle = block.type === "tabs" && field === "contentHtml";
      const currentHtml = mergeLegacyTitle ? tabsCompositionHtml(item) : item[field] ?? "";
      if (normalizeHtmlForInlineCompare(normalizedHtml) === normalizeHtmlForInlineCompare(normalizeTabsEditorFieldValue(field, currentHtml))) return;

      const nextState = await persistBlockActivityItems({ page, block }, (block.activityItems ?? []).map((candidate) =>
        candidate.id === itemId
          ? { ...candidate, [field]: normalizedHtml, ...(mergeLegacyTitle ? { contentTitle: null } : {}) }
          : candidate
      ));
      if (nextState) {
        await saveCommittedInlineSnapshot(
          projectPath,
          block.title || localizedActivityLabel(block.type),
          nextState.project.currentVersion ?? "autosave"
        );
      }
      const session = inlineRichTextSessionRef.current;
      if (session?.blockId === blockId && session.itemId === itemId && session.itemField === field) {
        setInlineRichTextSession({ ...session, lastSavedHtml: normalizedHtml });
      }
    });
    inlineRichTextCommitRef.current = pendingCommit.catch((error) => {
      void logDevEvent("error", "Panel inline rich-text commit failed", {
        blockId, itemId, field, error: error instanceof Error ? error.message : String(error)
      });
    });
    return pendingCommit;
  }

  function finishPanelInlineEditing(blockId: string) {
    const session = inlineRichTextSessionRef.current;
    const editor = richEditorRef.current;
    if (!session || session.blockId !== blockId || !session.itemId || !editor ||
      (session.itemField !== "title" && session.itemField !== "contentTitle" && session.itemField !== "contentHtml")) return;
    const html = cleanEditorHtmlForRichTextSession(editor.innerHTML || "<p></p>");
    const ticket = pendingInlineText.begin(richTextFieldKey(currentProjectPath, blockId, session.itemId, session.itemField), html);
    const completion = commitPanelInlineText(blockId, session.itemId, session.itemField, html);
    delete editor.dataset.paideiaRichTextDirty;
    void completion.then(() => pendingInlineText.settle(ticket, true), (error) => {
      pendingInlineText.settle(ticket, false);
      if (pendingInlineText.get(ticket.key)?.sequence === ticket.sequence) {
        window.dispatchEvent(new CustomEvent("paideia:inline-rich-text-save-failed", {
          detail: { editorKey: ticket.key, message: error instanceof Error ? error.message : String(error) }
        }));
      }
    });
    editor.blur();
    setInlineRichTextSession(null);
  }

  function renderTabsEditorRichTextFieldForBlock({
    block,
    className,
    field,
    html,
    item,
    label,
    placeholder,
    inLesson = false,
    onFinish
  }: {
    block: PaideiaBlock;
    className?: string;
    field: TabsRichTextFieldName;
    html: string;
    item: ActivityItem;
    label: string;
    placeholder: string;
    inLesson?: boolean;
    onFinish?: () => void;
  }) {
    const profile: RichTextToolbarProfile = "full";
    const allowTable = true;
    const isActive =
      inlineRichTextEdit?.blockId === block.id &&
      inlineRichTextEdit.itemId === item.id &&
      inlineRichTextEdit.itemField === field;
    const normalizedHtml = html?.trim() || tabsEditorFieldFallback(field);

    return (
      <div className={`inline-rich-text-wrapper tabs-inline-wrapper ${isActive ? "active" : ""}`}>
        {!inLesson ? <span className="editor-label">{label}</span> : null}
        {isActive ? (
          <RichTextToolbar
            displayMode="expanded"
            showOutline
            showTable={allowTable}
            className={inlineRichToolbarClassName()}
            onBeforeCommand={saveRichEditorSelection}
            onCaseTransform={applyCaseTransform}
            onClearFormatting={clearRichEditorFormatting}
            onCommand={runEditorCommand}
            onFontFamily={(fontFamily) => void applyEditorFontFamily(fontFamily)}
            onFontSize={applyEditorFontSize}
            onInsertInlineImage={profile === "full" ? (file) => void insertRichEditorInlineImage(file) : undefined}
            onInsertTable={insertRichTextTable}
            onLineHeight={applyEditorLineHeight}
            onLink={applyLink}
            onSelectAll={selectAllRichEditorText}
            onTextColorChange={applyEditorTextColor}
            profile={profile}
            blockFormat={richToolbarBlockFormat}
            fontFamily={richToolbarFontFamily}
            fontFamilies={richTextFontOptions}
            fontSize={richToolbarFontSize}
            lineHeight={richToolbarLineHeight}
            contextState={richToolbarContextState}
            textColor={textColor}
          />
        ) : null}
        <InlineRichTextField key={richTextFieldKey(currentProjectPath, block.id, item.id, field)} editorKey={richTextFieldKey(currentProjectPath, block.id, item.id, field)}
          commitOnUnmount={inLesson}
          commitOnInput={false}
          className={className}
          html={normalizedHtml}
          isActive={isActive}
          onActivate={(editor, initialHtml) =>
            handleTabsEditorRichTextActivate(editor, block, item, field, initialHtml, profile)
          }
          onBeforeRichInput={handleRichEditorBeforeInput}
          onCommit={(nextHtml) => {
            if (!inLesson) {
              handleTabsEditorRichTextCommit(block.id, item.id, field, nextHtml);
              return;
            }
            const pendingCommit = commitPanelInlineText(block.id, item.id, field, nextHtml);
            onFinish?.();
            const session = inlineRichTextSessionRef.current;
            if (session?.blockId === block.id && session.itemId === item.id && session.itemField === field) {
              setInlineRichTextSession(null);
            }
            return pendingCommit;
          }}
          onInput={(nextHtml) => updateInlineRichTextCurrentHtml(nextHtml)}
          onLiveInput={handleRichEditorLiveInput}
          onRequestClose={() => { setInlineRichTextSession(null); onFinish?.(); }}
          placeholder={placeholder}
        />
        {isActive ? <RichTextTableController getEditor={() => richEditorRef.current} onChange={syncRichEditorHtml} /> : null}
      </div>
    );
  }

