  function normalizeActivityItemEditorRichTextValue(field: ActivityItemEditorRichTextField, html: string) {
    const fallback = field === "contentHtml" ? "<p></p>" : "";
    const normalized = normalizeFrenchTypographyInHtml(html?.trim() || fallback);
    return tabsEditorFieldHasMeaningfulHtml(normalized) ? normalized : "";
  }

  function handleActivityItemEditorRichTextActivate(
    editor: HTMLDivElement,
    block: PaideiaBlock,
    item: ActivityItem,
    field: ActivityItemEditorRichTextField,
    html: string,
    profile: RichTextToolbarProfile
  ) {
    richEditorRef.current = editor;
    const currentSession = inlineRichTextSessionRef.current;
    const sessionKey = richToolbarSessionKey(block.id, item.id, field);
    const isNewSession =
      !currentSession ||
      currentSession.blockId !== block.id ||
      currentSession.itemId !== item.id ||
      currentSession.itemField !== field;
    if (isNewSession) {
      const initialHtml = html?.trim() || (field === "contentHtml" ? "<p></p>" : "");
      const currentValue = (item[field] as string | null | undefined)?.trim() || initialHtml;
      initializeRichToolbarColorForSession(editor, sessionKey);
      setInlineRichTextSession({
        blockId: block.id,
        itemId: item.id,
        itemField: field,
        profile,
        originalHtml: initialHtml,
        currentHtml: currentValue,
        lastSavedHtml: currentValue,
        snapshotCreated: false
      });
    } else {
      refreshPendingRichToolbarColorForSession(editor, sessionKey);
    }
    saveRealRichEditorSelection();
  }

  function handleActivityItemEditorRichTextCommit(
    blockId: string,
    itemId: string,
    field: ActivityItemEditorRichTextField,
    html: string
  ) {
    if (!isCurrentBlockForm(blockId)) return;
    const normalizedHtml = normalizeActivityItemEditorRichTextValue(field, html);

    setBlockForm((current) => {
      const currentItem = current.activityItems.find((item) => item.id === itemId);
      const currentHtml = (currentItem?.[field] as string | null | undefined)?.trim() || "";
      if (normalizeHtmlForInlineCompare(normalizedHtml) === normalizeHtmlForInlineCompare(currentHtml)) {
        return current;
      }
      return {
        ...current,
        activityItems: current.activityItems.map((item) =>
          item.id === itemId
            ? {
                ...item,
                [field]: normalizedHtml
              }
            : item
        )
      };
    });

    const updatedSession = inlineRichTextSessionRef.current;
    if (updatedSession?.blockId === blockId && updatedSession.itemId === itemId && updatedSession.itemField === field) {
      setInlineRichTextSession({
        ...updatedSession,
        currentHtml: normalizedHtml,
        lastSavedHtml: normalizedHtml
      });
    }

    window.setTimeout(() => {
      const activeElement = document.activeElement;
      if (
        activeElement instanceof HTMLElement &&
        (activeElement.closest(".inline-rich-text-wrapper") ||
          activeElement.closest("[data-rich-text-toolbar='true'], [data-rich-text-dialog='true']"))
      ) {
        return;
      }
      setInlineRichTextSession(null);
    }, 0);
  }

