  function renderCardSortRichTextFieldForBlock({ block, categoryId, field, html, label, placeholder }: {
    block: PaideiaBlock;
    field: "successFeedbackHtml" | "failureFeedbackHtml" | "categoryLabelHtml";
    categoryId?: string;
    html: string;
    label: string;
    placeholder: string;
  }) {
    const profile: RichTextToolbarProfile = "full";
    const itemId = categoryId ? `card-sort-category:${categoryId}` : "card-sort-feedbacks";
    const isActive = inlineRichTextEdit?.blockId === block.id && inlineRichTextEdit.itemId === itemId && inlineRichTextEdit.itemField === field;
    const normalizedHtml = html?.trim() || "<p></p>";
    const commit = (nextHtml: string) => {
      if (!isCurrentBlockForm(block.id)) return;
      const normalized = normalizeFrenchTypographyInHtml(nextHtml?.trim() || "<p></p>");
      // Card Sort global feedbacks are saved through blockFormRef.current.
      // Keep the ref synchronized immediately: relying only on setBlockForm()
      // can leave handleSaveBlock() reading the previous feedback value when
      // the editor blur and the Save click happen in the same interaction.
      const currentForm = blockFormRef.current;
      const currentCardSort = normalizeCardSortData(currentForm.cardSort);
      const nextCardSort = categoryId
        ? {
            ...currentCardSort,
            categories: currentCardSort.categories.map((category) => category.id === categoryId
              ? { ...category, labelHtml: normalized, label: stripHtmlForEditor(normalized).replace(/\s+/g, " ").trim() || category.label }
              : category)
          }
        : { ...currentCardSort, [field]: normalized };
      const nextForm = { ...currentForm, cardSort: nextCardSort };
      blockFormRef.current = nextForm;
      setBlockForm(nextForm);
      const session = inlineRichTextSessionRef.current;
      if (session?.blockId === block.id && session.itemId === itemId && session.itemField === field) {
        setInlineRichTextSession({ ...session, currentHtml: normalized, lastSavedHtml: normalized });
      }
      window.setTimeout(() => {
        const activeElement = document.activeElement;
        if (
          activeElement instanceof HTMLElement &&
          (activeElement.closest(".inline-rich-text-wrapper") ||
            activeElement.closest("[data-rich-text-toolbar='true'], [data-rich-text-dialog='true']"))
        ) {
          return;
        }
        setInlineRichTextSession(null);
      }, 0);
    };
    return <div className={`inline-rich-text-wrapper activity-item-editor-rich-wrapper card-sort-rich-text-wrapper ${isActive ? "active" : ""}`}>
      <span className="editor-label">{label}</span>
      {isActive ? createPortal(<RichTextToolbar showOutline className={inlineRichToolbarClassName("card-sort-inline-rich-toolbar")} onBeforeCommand={saveRichEditorSelection} onCaseTransform={applyCaseTransform} onClearFormatting={clearRichEditorFormatting} onCommand={runEditorCommand} onFontFamily={(fontFamily) => void applyEditorFontFamily(fontFamily)} onFontSize={applyEditorFontSize} onInsertInlineImage={(file) => void insertRichEditorInlineImage(file)} onLineHeight={applyEditorLineHeight} onLink={applyLink} onSelectAll={selectAllRichEditorText} onTextColorChange={applyEditorTextColor} profile={profile} blockFormat={richToolbarBlockFormat} fontFamily={richToolbarFontFamily} fontFamilies={richTextFontOptions} fontSize={richToolbarFontSize} lineHeight={richToolbarLineHeight} contextState={richToolbarContextState} showInlineImage={field !== "categoryLabelHtml"} textColor={textColor} />, document.body) : null}
      <InlineRichTextField key={richTextFieldKey(currentProjectPath, block.id, itemId, field)} editorKey={richTextFieldKey(currentProjectPath, block.id, itemId, field)} commitOnInput={false} html={normalizedHtml} isActive={isActive} onActivate={(editor, initialHtml) => {
        richEditorRef.current = editor;
        const sessionKey = richToolbarSessionKey(block.id, itemId, field);
        const currentSession = inlineRichTextSessionRef.current;
        if (!currentSession || currentSession.blockId !== block.id || currentSession.itemId !== itemId || currentSession.itemField !== field) {
          initializeRichToolbarColorForSession(editor, sessionKey);
          setInlineRichTextSession({ blockId: block.id, itemId, itemField: field, profile, originalHtml: initialHtml, currentHtml: html || initialHtml, lastSavedHtml: html || initialHtml, snapshotCreated: false });
        } else refreshPendingRichToolbarColorForSession(editor, sessionKey);
        saveRealRichEditorSelection();
      }} onBeforeRichInput={handleRichEditorBeforeInput} onCommit={commit} onInput={updateInlineRichTextCurrentHtml} onLiveInput={handleRichEditorLiveInput} onRequestClose={() => setInlineRichTextSession(null)} placeholder={placeholder} />
    </div>;
  }

