  function markerRichTextFieldHasMeaningfulHtml(value: string | null | undefined) {
    if (!value) {
      return false;
    }
    if (/<img\b/i.test(value)) {
      return true;
    }
    return Boolean(stripHtmlForEditor(value).replace(/\s+/g, " ").trim());
  }

  function normalizePointOfInterestMarkerRichTextValue(field: PointOfInterestMarkerRichTextField, html: string) {
    const fallback = field === "contentHtml" ? "<p></p>" : "";
    const normalized = normalizeFrenchTypographyInHtml(html?.trim() || fallback);
    return markerRichTextFieldHasMeaningfulHtml(normalized) ? normalized : "";
  }

  function handlePointOfInterestMarkerRichTextActivate(
    editor: HTMLDivElement,
    block: PaideiaBlock,
    marker: PointOfInterestMarker,
    field: PointOfInterestMarkerRichTextField,
    html: string,
    profile: RichTextToolbarProfile
  ) {
    richEditorRef.current = editor;
    const currentSession = inlineRichTextSessionRef.current;
    const sessionKey = richToolbarSessionKey(block.id, marker.id, field);
    const isNewSession =
      !currentSession ||
      currentSession.blockId !== block.id ||
      currentSession.itemId !== marker.id ||
      currentSession.itemField !== field;
    if (isNewSession) {
      const initialHtml = html?.trim() || (field === "contentHtml" ? "<p></p>" : "");
      const currentValue = (marker[field] as string | null | undefined)?.trim() || initialHtml;
      initializeRichToolbarColorForSession(editor, sessionKey);
      setInlineRichTextSession({
        blockId: block.id,
        itemId: marker.id,
        itemField: field,
        profile,
        originalHtml: initialHtml,
        currentHtml: currentValue,
        lastSavedHtml: currentValue,
        snapshotCreated: false
      });
    } else {
      refreshPendingRichToolbarColorForSession(editor, sessionKey);
    }
    saveRealRichEditorSelection();
  }

  function handlePointOfInterestMarkerRichTextCommit(
    blockId: string,
    markerId: string,
    field: PointOfInterestMarkerRichTextField,
    html: string
  ) {
    if (!isCurrentBlockForm(blockId)) return;
    const normalizedHtml = normalizePointOfInterestMarkerRichTextValue(field, html);

    setBlockForm((current) => {
      const currentMarker = current.pointOfInterestMarkers.find((marker) => marker.id === markerId);
      const currentHtml = (currentMarker?.[field] as string | null | undefined)?.trim() || "";
      if (normalizeHtmlForInlineCompare(normalizedHtml) === normalizeHtmlForInlineCompare(currentHtml)) {
        return current;
      }
      return {
        ...current,
        pointOfInterestMarkers: current.pointOfInterestMarkers.map((marker) =>
          marker.id === markerId
            ? {
                ...marker,
                [field]: normalizedHtml
              }
            : marker
        )
      };
    });

    const updatedSession = inlineRichTextSessionRef.current;
    if (updatedSession?.blockId === blockId && updatedSession.itemId === markerId && updatedSession.itemField === field) {
      setInlineRichTextSession({
        ...updatedSession,
        currentHtml: normalizedHtml,
        lastSavedHtml: normalizedHtml
      });
    }

    window.setTimeout(() => {
      const activeElement = document.activeElement;
      if (activeElement instanceof HTMLElement && activeElement.closest(".inline-rich-text-wrapper")) {
        return;
      }
      setInlineRichTextSession(null);
    }, 0);
  }

