  async function handleUploadSituationalDialogueCharacterPose(
    characterId: string,
    poseId: string,
    file: File
  ) {
    if (!selectedBlock || !currentProjectPath || !activePage) {
      return;
    }
    const character = blockForm.situationalDialogueCharacters.find((candidate) => candidate.id === characterId);
    if (!character) {
      return;
    }

    await runAction("upload-situational-dialogue-character-pose", async () => {
      const assetRef = await uploadSituationalDialogueCharacterAsset(
        currentProjectPath,
        selectedBlock.id,
        character.name,
        poseId,
        file
      );
      updateSituationalDialogueCharacter(characterId, {
        poses: character.poses.map((pose) => (pose.id === poseId ? { ...pose, assetRef } : pose))
      });
    });
  }

  function moveActivityItem(itemId: string, direction: -1 | 1) {
    setBlockForm((current) => {
      if (selectedBlock?.type === "slides") {
        const activityItems = normalizeSlidesActivityItems(current.activityItems);
        const index = activityItems.findIndex((item) => item.id === itemId);
        const nextIndex = index + direction;
        if (index < 0 || nextIndex < 0 || nextIndex >= activityItems.length) {
          return current;
        }
        const nextItems = [...activityItems];
        const [item] = nextItems.splice(index, 1);
        nextItems.splice(nextIndex, 0, item);
        return {
          ...current,
          activityItems: nextItems
        };
      }
      const activityItems = current.activityItems;
      const index = activityItems.findIndex((item) => item.id === itemId);
      const nextIndex = index + direction;
      if (index < 0 || nextIndex < 0 || nextIndex >= activityItems.length) {
        return current;
      }
      const nextItems = [...current.activityItems];
      const [item] = nextItems.splice(index, 1);
      nextItems.splice(nextIndex, 0, item);
      return {
        ...current,
        activityItems: nextItems
      };
    });
  }

  function toggleActivityItemCollapse(itemId: string) {
    setCollapsedActivityItemIds((current) =>
      current.includes(itemId)
        ? current.filter((id) => id !== itemId)
        : [...current, itemId]
    );
  }

  function updateBlockImageAssetLocally(
    blockId: string,
    assetRefs: string[],
    mediaFileName: string,
    annotation: { stateRef: string | null; sourceAssetRef: string | null } = {
      stateRef: null,
      sourceAssetRef: null
    }
  ) {
    setWorkspaceState((current) => current ? {
      ...current,
      project: {
        ...current.project,
        course: {
          ...current.project.course,
          modules: current.project.course.modules.map((module) => ({
            ...module,
            chapters: module.chapters.map((chapter) => ({
              ...chapter,
              pages: chapter.pages.map((page) => ({
                ...page,
                blocks: page.blocks.map((block) => block.id === blockId ? {
                  ...block,
                  assetRefs,
                  mediaFileName,
                  imageCrop: null,
                  imageAccessibility: null,
                  imageAnnotationStateRef: annotation.stateRef,
                  imageAnnotationSourceAssetRef: annotation.sourceAssetRef
                } : block)
              }))
            }))
          }))
        }
      }
    } : current);
    const mediaDraft = {
      blockId,
      assetRefs,
      mediaFileName,
      imageCrop: null,
      imageAnnotationStateRef: annotation.stateRef,
      imageAnnotationSourceAssetRef: annotation.sourceAssetRef
    };
    pendingBlockMediaDraftRef.current = mediaDraft;
    setPendingBlockMediaDraft(mediaDraft);
    setBlockForm((current) => ({
      ...current,
      mediaFileName,
      imageCrop: null
    }));
    setDraftImageCrop(null);
    setIsCropMode(false);
  }

  async function discardBlockImageAnnotation(blockId: string) {
    await clearBlockImageAnnotationState(currentProjectPath, blockId);
    setActiveBlockImageAnnotationId((current) => current === blockId ? null : current);
    setWorkspaceState((current) => current ? {
      ...current,
      project: {
        ...current.project,
        course: {
          ...current.project.course,
          modules: current.project.course.modules.map((module) => ({
            ...module,
            chapters: module.chapters.map((chapter) => ({
              ...chapter,
              pages: chapter.pages.map((page) => ({
                ...page,
                blocks: page.blocks.map((block) => block.id === blockId ? {
                  ...block,
                  imageAnnotationStateRef: null,
                  imageAnnotationSourceAssetRef: null
                } : block)
              }))
            }))
          }))
        }
      }
    } : current);
    setBlockImageAnnotationDocuments((current) => {
      const next = { ...current };
      delete next[blockId];
      return next;
    });
    setBlockImageAnnotationSourceRefs((current) => {
      const next = { ...current };
      delete next[blockId];
      return next;
    });
    setPendingBlockMediaDraft((current) => {
      if (current?.blockId !== blockId) {
        return current;
      }
      const next = {
        ...current,
        imageAnnotationStateRef: null,
        imageAnnotationSourceAssetRef: null
      };
      pendingBlockMediaDraftRef.current = next;
      return next;
    });
    setBlockForm((current) => ({
      ...current,
      imageAnnotationStateRef: null,
      imageAnnotationSourceAssetRef: null
    }));
  }

  async function handleExportLibraryProjectPaideia(entry: LibraryProjectEntry) {
    setLibraryActionMenu(null);
    const includeResources = await chooseArchiveBanks("export");
    if (includeResources === null) return;
    const defaultPath = `${importDestinationRoot.replace(/\\/g, "/")}/archives/${paideiaArchiveFileName(entry.title)}`;
    const targetPath = await save({
      defaultPath,
      filters: [{ name: "Leçon PAIDEIA", extensions: ["paideia"] }]
    });
    if (!targetPath) {
      return;
    }

    await runAction("export-library-paideia", async () => {
      await exportPaideiaArchiveTo(entry.archivePath, targetPath, includeResources);
      await refreshLibraryProjects();
    });
  }

  async function toggleBlockImageAnnotation() {
    if (!selectedBlock || selectedBlock.type !== "image-text") {
      return;
    }
    setIsCropMode(false);
    setDraftImageCrop(null);
    if (activeBlockImageAnnotationId === selectedBlock.id) {
      setActiveBlockImageAnnotationId(null);
      return;
    }

    const currentImageRef = firstAssetRef(selectedBlock.assetRefs, isSupportedImageAsset);
    if (!currentImageRef) {
      return;
    }
    try {
      const state = await loadBlockImageAnnotationState(currentProjectPath, selectedBlock.id);
      const sourceAssetRef =
        state?.sourceAssetRef || currentImageRef;
      setBlockImageAnnotationDocuments((current) => ({
        ...current,
        [selectedBlock.id]: state?.document ?? { version: 1, annotations: [] }
      }));
      setBlockImageAnnotationSourceRefs((current) => ({
        ...current,
        [selectedBlock.id]: sourceAssetRef
      }));
      setBlockForm((current) => ({
        ...current,
        imageAnnotationStateRef: state ? `wip/annotations/${selectedBlock.id}/block-image.json` : null,
        imageAnnotationSourceAssetRef: sourceAssetRef
      }));
      setActiveBlockImageAnnotationId(selectedBlock.id);
    } catch (error) {
      console.error("Impossible de charger l'etat d'annotation du bloc.", error);
    }
  }

  function closeBlockImageAnnotation() {
    setActiveBlockImageAnnotationId(null);
  }

  async function updateBlockImageAnnotation(
    blockId: string,
    sourceAssetRef: string,
    document: NativeImageAnnotationDocument,
    renderedDataUrl?: string | null
  ) {
    if (!selectedBlock || selectedBlock.id !== blockId || selectedBlock.type !== "image-text") {
      return;
    }

    const nonImageAssetRefs = (selectedBlock.assetRefs ?? []).filter((assetRef) => !isSupportedImageAsset(assetRef));
    if (!document.annotations.length) {
      await clearBlockImageAnnotationState(currentProjectPath, blockId);
      const assetRefs = [sourceAssetRef, ...nonImageAssetRefs.filter((assetRef) => assetRef !== sourceAssetRef)];
      updateBlockImageAssetLocally(
        blockId,
        assetRefs,
        assetDisplayName(sourceAssetRef) || blockForm.mediaFileName || "image.png",
        { stateRef: null, sourceAssetRef: null }
      );
      setBlockImageAnnotationDocuments((current) => ({ ...current, [blockId]: document }));
      return;
    }

    if (!renderedDataUrl) {
      return;
    }
    const result = await saveActivityItemAnnotation({
      projectPath: currentProjectPath,
      blockId,
      itemId: "block-image",
      sourceAssetRef,
      document,
      imageFileName: `${blockId}-annotation.png`,
      imageBytes: await dataUrlToBytes(renderedDataUrl)
    });
    const assetRefs = [
      result.annotatedAssetRef,
      ...nonImageAssetRefs.filter((assetRef) => assetRef !== result.annotatedAssetRef && assetRef !== sourceAssetRef)
    ];
    updateBlockImageAssetLocally(
      blockId,
      assetRefs,
      assetDisplayName(result.annotatedAssetRef) || "image-annotee.png",
      { stateRef: result.stateRef, sourceAssetRef: result.sourceAssetRef }
    );
    setBlockImageAnnotationDocuments((current) => ({ ...current, [blockId]: document }));
    setBlockImageAnnotationSourceRefs((current) => ({ ...current, [blockId]: result.sourceAssetRef }));
    setBlockForm((current) => ({
      ...current,
      imageAnnotationStateRef: result.stateRef,
      imageAnnotationSourceAssetRef: result.sourceAssetRef
    }));
  }

  async function applyBlockImageAnnotation() {
    const editedBlockId = selectedBlock?.id ?? null;
    await latestHandleSaveBlockRef.current?.({ closeInspector: false });
    setActiveBlockImageAnnotationId(null);
    await waitForNextPaint();
    if (editedBlockId) {
      focusBlock(editedBlockId, "auto", "center");
    }
  }

  function beginSelectedBlockCropDirect() {
    setActiveBlockImageAnnotationId(null);
    setDraftImageCrop(normalizeImageCrop(blockForm.imageCrop) ?? null);
    setIsCropMode(true);
  }

  async function toggleSelectedBlockCrop() {
    if (!selectedBlock) {
      return;
    }
    if (isCropMode) {
      cancelImageCrop();
      return;
    }
    if (selectedBlock.type === "image-text") {
      const cachedDocument = blockImageAnnotationDocuments[selectedBlock.id];
      const state = cachedDocument?.annotations.length
        ? { document: cachedDocument }
        : await loadBlockImageAnnotationState(currentProjectPath, selectedBlock.id);
      if (state?.document.annotations.length) {
        setBlockAnnotationCropWarningId(selectedBlock.id);
        return;
      }
    }
    beginSelectedBlockCropDirect();
  }

  async function confirmBlockAnnotationCropWarning() {
    const blockId = blockAnnotationCropWarningId;
    setBlockAnnotationCropWarningId(null);
    if (!blockId) {
      return;
    }
    await discardBlockImageAnnotation(blockId);
    beginSelectedBlockCropDirect();
  }

  function hasActivityItemAnnotation(item: ActivityItem) {
    return Boolean(item.imageAnnotationStateRef?.trim());
  }

  function beginActivityItemCropDirect(item: ActivityItem, face?: "front" | "back") {
    setActiveActivityItemAnnotationId(null);
    setActiveActivityItemCropId(face ? `${item.id}:${face}` : item.id);
    setDraftImageCrop(normalizeImageCrop(
      face === "front" ? item.frontImageCrop : face === "back" ? item.backImageCrop : item.imageCrop
    ) ?? null);
    setIsCropMode(true);
  }

  function beginActivityItemCrop(item: ActivityItem, face?: "front" | "back") {
    if (!face && hasActivityItemAnnotation(item)) {
      setAnnotationCropWarningDialog({ item });
      return;
    }
    beginActivityItemCropDirect(item, face);
  }

  function confirmAnnotationCropWarning() {
    const item = annotationCropWarningDialog?.item;
    setAnnotationCropWarningDialog(null);
    if (item) {
      beginActivityItemCropDirect(item);
    }
  }

  async function toggleActivityItemAnnotation(item: ActivityItem) {
    setActiveActivityItemCropId(null);
    setDraftImageCrop(null);
    setIsCropMode(false);
    if (activeActivityItemAnnotationId === item.id) {
      setActiveActivityItemAnnotationId(null);
      return;
    }
    if (item.imageAnnotationStateRef) {
      try {
        const state = await loadActivityItemAnnotationState(currentProjectPath, item.imageAnnotationStateRef);
        if (state?.document) {
          setActivityItemAnnotationDocuments((current) => ({
            ...current,
            [item.id]: state.document
          }));
        }
        if (state?.sourceAssetRef) {
          updateActivityItem(item.id, {
            imageAnnotationSourceAssetRef: state.sourceAssetRef
          });
        }
      } catch (error) {
        console.error("Impossible de charger l'etat d'annotation.", error);
      }
    } else {
      setActivityItemAnnotationDocuments((current) => ({
        ...current,
        [item.id]: { version: 1, annotations: [] }
      }));
    }
    setActiveActivityItemAnnotationId(item.id);
  }

  function closeActivityItemAnnotation() {
    setActiveActivityItemAnnotationId(null);
  }

  async function applyActivityItemAnnotation() {
    const editedBlockId = selectedBlock?.id ?? null;
    await latestHandleSaveBlockRef.current?.({ closeInspector: false });
    setActiveActivityItemAnnotationId(null);
    await waitForNextPaint();
    if (editedBlockId) {
      focusBlock(editedBlockId, "auto", "center");
    }
  }

  async function applyActivityItemCrop() {
    if (!activeActivityItemCropId || activityItemCropCommitRef.current) {
      return;
    }

    activityItemCropCommitRef.current = true;

    let completed = false;
    try {
      const [activeItemId, activeFace] = activeActivityItemCropId.split(":") as [string, "front" | "back" | undefined];
      const item = blockForm.activityItems.find((candidate) => candidate.id === activeItemId);
      const nextCrop = normalizeImageCrop(draftImageCrop);
      const imageAssetRef = item
        ? activeFace === "front"
          ? item.frontImageAssetRef
          : activeFace === "back"
            ? item.backImageAssetRef
            : firstItemImageAssetRef(item)
        : null;
      const imageAsset = buildAssetUrl(currentProjectPath, imageAssetRef);
      if (item && nextCrop && imageAsset && imageAssetRef && selectedBlock && activePage) {
        const sourceName = (activeFace === "front"
          ? item.frontImageFileName
          : activeFace === "back"
            ? item.backImageFileName
            : item.mediaFileName) || assetDisplayName(imageAssetRef) || "image.png";
        const croppedFile = await createCroppedImageFile(imageAsset, sourceName, nextCrop, {
          containInSquare: selectedBlock.type === "image-grid"
        });
        if (!croppedFile) {
          return;
        }
        const nextState = await persistActivityItemCrop(
          currentProjectPath,
          activePage.id,
          selectedBlock.id,
          item.id,
          activeFace ?? null,
          croppedFile
        );
        const updatedBlock = flattenPages(nextState.project)
          .flatMap((page) => page.blocks)
          .find((block) => block.id === selectedBlock.id);
        setWorkspaceState(nextState);
        if (updatedBlock) {
          setBlockForm((current) => {
            const next = {
              ...current,
              activityItems: updatedBlock.activityItems ?? current.activityItems
            };
            blockFormRef.current = next;
            return next;
          });
        }
      } else {
        updateActivityItem(activeItemId, activeFace === "front"
          ? { frontImageCrop: nextCrop ?? null }
          : activeFace === "back"
            ? { backImageCrop: nextCrop ?? null }
            : {
                imageCrop: nextCrop ?? null,
                imageAnnotationStateRef: null,
                imageAnnotationSourceAssetRef: null
              });
      }
      completed = true;
    } finally {
      activityItemCropCommitRef.current = false;
      if (completed) {
        setActiveActivityItemCropId(null);
        setDraftImageCrop(null);
        setIsCropMode(false);
      }
    }
  }

  function cancelActivityItemCrop() {
    setActiveActivityItemCropId(null);
    setDraftImageCrop(null);
    setIsCropMode(false);
  }

  async function updateActivityItemAnnotation(
    itemId: string,
    sourceAssetRef: string,
    document: NativeImageAnnotationDocument,
    renderedDataUrl?: string | null
  ) {
    const currentItem = blockFormRef.current.activityItems.find((item) => item.id === itemId);
    if (!currentItem) {
      return;
    }

    if (!document.annotations.length) {
      updateActivityItem(itemId, {
        assetRefs: [
          sourceAssetRef,
          ...(currentItem.assetRefs ?? []).filter((assetRef) =>
            assetRef !== sourceAssetRef && !isSupportedImageAsset(assetRef)
          )
        ],
        imageAnnotationStateRef: null,
        imageAnnotationSourceAssetRef: null
      });
      setActivityItemAnnotationDocuments((current) => ({
        ...current,
        [itemId]: document
      }));
      return;
    }

    if (!renderedDataUrl) {
      return;
    }

    const imageBytes = await dataUrlToBytes(renderedDataUrl);
    const result = await saveActivityItemAnnotation({
      projectPath: currentProjectPath,
      blockId: selectedBlock?.id ?? "",
      itemId,
      sourceAssetRef,
      document,
      imageFileName: `${itemId}-annotation.png`,
      imageBytes
    });
    updateActivityItem(itemId, {
      assetRefs: [
        result.annotatedAssetRef,
        ...(currentItem.assetRefs ?? []).filter((assetRef) =>
          assetRef !== result.annotatedAssetRef && assetRef !== sourceAssetRef && !isSupportedImageAsset(assetRef)
        )
      ],
      imageCrop: null,
      imageAnnotationStateRef: result.stateRef,
      imageAnnotationSourceAssetRef: result.sourceAssetRef
    });
    setActivityItemAnnotationDocuments((current) => ({
      ...current,
      [itemId]: document
    }));
  }

  async function handleUploadActivityItemAsset(itemId: string, file: File, flipCardFace?: "front" | "back") {
    if (!selectedBlock || !activePage) {
      return;
    }
    const isAudioTrackUpload = selectedBlock.type === "audio";
    if (!isAudioTrackUpload && !await acceptActivityImageImport(file)) return;
    const inferredAudioTrackTitle = selectedBlock.type === "audio" ? await inferAudioTrackTitle(file) : "";
    const mediaKind = selectedBlock.type === "audio" ? "audio" : "image";
    const reuseAssetRef = await chooseExistingDuplicateAsset(file, mediaKind);

    setEditorOriginalMedia((current) =>
      current?.blockId === selectedBlock.id
        ? current
        : {
            blockId: selectedBlock.id,
            assetRefs: [...(selectedBlock.assetRefs ?? [])],
            subtitleRefs: [...(selectedBlock.subtitleRefs ?? [])],
            videoSubtitleOriginalRef: selectedBlock.videoSubtitleOriginalRef ?? null,
            mediaFileName: selectedBlock.mediaFileName ?? "",
            imageCrop: normalizeImageCrop(selectedBlock.imageCrop) ?? null,
            activityItems: selectedBlock.activityItems ?? []
          }
    );

    if (isAudioTrackUpload) {
      setImportDialog({
        status: "running",
        title: t("media.loadingAudio")
      });
    }

    try {
      await runAction("upload-activity-item-media", async () => {
        const previousAssets = selectedBlock.assetRefs ?? [];
        const nextState = await uploadBlockAsset(currentProjectPath, selectedBlock.id, file, isAudioTrackUpload ? "media" : "image", reuseAssetRef);
        const nextBlock = flattenPages(nextState.project)
          .flatMap((page) => page.blocks)
          .find((block) => block.id === selectedBlock.id);
        const nextAssets = nextBlock?.assetRefs ?? [];
        const uploadedAsset = reuseAssetRef
          ?? nextAssets.find((assetRef) => !previousAssets.includes(assetRef))
          ?? nextAssets[nextAssets.length - 1];

        if (!uploadedAsset) {
          setWorkspaceState(nextState);
          return;
        }

        const updatedActivityItems = blockForm.activityItems.map((item) =>
          item.id === itemId
            ? (selectedBlock.type === "flip-cards" || selectedBlock.type === "card-sort") && flipCardFace
              ? flipCardFace === "front"
                ? {
                    ...item,
                    assetRefs: [uploadedAsset, ...(item.assetRefs ?? []).filter((assetRef) => assetRef !== uploadedAsset && assetRef !== item.frontImageAssetRef)],
                    frontType: "image" as const,
                    frontImageAssetRef: uploadedAsset,
                    frontImageFileName: file.name,
                    frontImageCrop: null
                  }
                : {
                    ...item,
                    assetRefs: [uploadedAsset, ...(item.assetRefs ?? []).filter((assetRef) => assetRef !== uploadedAsset && assetRef !== item.backImageAssetRef)],
                    backType: "image" as const,
                    backImageAssetRef: uploadedAsset,
                    backImageFileName: file.name,
                    backImageCrop: null
                  }
              : {
                ...item,
                assetRefs: [
                  uploadedAsset,
                  ...(item.assetRefs ?? []).filter((assetRef) =>
                    selectedBlock.type === "audio"
                      ? !isSupportedAudioAsset(assetRef)
                      : assetRef !== uploadedAsset
                  )
                ],
                imageCrop: selectedBlock.type === "audio" ? item.imageCrop ?? null : null,
                imageAccessibility: selectedBlock.type === "audio" ? item.imageAccessibility ?? null : null,
                imageAnnotationStateRef: null,
                imageAnnotationSourceAssetRef: null,
                mediaFileName: file.name,
                title: selectedBlock.type === "audio" && inferredAudioTrackTitle ? inferredAudioTrackTitle : item.title,
                frontType: item.frontType
              }
            : item
        );
        const nextBlockAssetRefs =
          selectedBlock.type === "audio"
            ? (selectedBlock.assetRefs ?? []).filter((assetRef) => isSupportedImageAsset(assetRef))
            : nextBlock?.assetRefs ?? nextAssets;

        const updatedState = await updateBlock({
          projectPath: currentProjectPath,
          pageId: activePage.id,
          blockId: selectedBlock.id,
          blockType: selectedBlock.type,
          title: selectedBlock.title,
          summary: selectedBlock.summary,
          contentHtml: selectedBlock.contentHtml ?? null,
          quoteAuthorHtml: selectedBlock.quoteAuthorHtml ?? null,
          quoteShowAuthor: selectedBlock.quoteShowAuthor ?? null,
          mediaLayout: selectedBlock.mediaLayout ?? null,
          imageSize: selectedBlock.imageSize ?? null,
          contentWidth: selectedBlock.contentWidth ?? null,
          contentAlign: selectedBlock.contentAlign ?? null,
          mediaGap: selectedBlock.mediaGap ?? null,
          verticalAlign: selectedBlock.verticalAlign ?? null,
          imageRounded: selectedBlock.imageRounded ?? null,
          mediaFileName: selectedBlock.mediaFileName ?? null,
          imageCrop: selectedBlock.imageCrop ?? null,
          imageAccessibility: selectedBlock.imageAccessibility ?? null,
          buttonBackgroundColor: selectedBlock.buttonBackgroundColor ?? null,
          buttonTextColor: selectedBlock.buttonTextColor ?? null,
          panelBackgroundColor: selectedBlock.panelBackgroundColor ?? null,
          panelBorderColor: selectedBlock.panelBorderColor ?? null,
          panelBorderWidth: selectedBlock.panelBorderWidth ?? null,
          panelBorderStyle: selectedBlock.panelBorderStyle ?? null,
          panelPadding: selectedBlock.panelPadding ?? null,
          panelRounded: selectedBlock.panelRounded ?? null,
          panelShadow: selectedBlock.panelShadow ?? null,
          noteIcon: selectedBlock.noteIcon ?? null,
          noteShowIcon: selectedBlock.noteShowIcon ?? null,
          noteIconColor: selectedBlock.noteIconColor ?? null,
          noteIconMatchesBorder: selectedBlock.noteIconMatchesBorder ?? null,
          dividerColor: selectedBlock.dividerColor ?? null,
          dividerWidth: selectedBlock.dividerWidth ?? null,
          dividerStyle: selectedBlock.dividerStyle ?? null,
          markerScheme: selectedBlock.markerScheme ?? null,
          markerTextColor: selectedBlock.markerTextColor ?? null,
          markerType: selectedBlock.markerType ?? null,
          pointOfInterestMarkers: selectedBlock.pointOfInterestMarkers ?? [],
          cardSort:
            selectedBlock.type === "card-sort"
              ? normalizeCardSortData(blockFormRef.current.cardSort)
              : null,
          activityItems: updatedActivityItems,
          markerPopupWidth: selectedBlock.markerPopupWidth ?? null,
          markerPopupHeight: selectedBlock.markerPopupHeight ?? null,
          assetRefs: nextBlockAssetRefs,
          subtitleRefs: nextBlock?.subtitleRefs ?? selectedBlock.subtitleRefs ?? [],
          videoSubtitleOriginalRef:
            nextBlock?.videoSubtitleOriginalRef ?? selectedBlock.videoSubtitleOriginalRef ?? null
        });

        setBlockForm((current) => {
          const next = {
            ...current,
            activityItems: updatedActivityItems
          };
          blockFormRef.current = next;
          return next;
        });

        setWorkspaceState(updatedState);
      });

      if (isAudioTrackUpload) {
        setImportDialog(null);
      }
    } catch (error) {
      if (isAudioTrackUpload) {
        setImportDialog({
          status: "error",
          doneTitle: t("import.loadingInterrupted"),
          message: error instanceof Error ? error.message : t("media.audioLoadFailed")
        });
        return;
      }
      throw error;
    }
  }

  function removeActivityItem(itemId: string) {
    setBlockForm((current) => {
      const nextActivityItems = selectedBlock?.type === "slides"
        ? normalizeSlidesActivityItems(current.activityItems).filter((item) => item.id !== itemId)
        : selectedBlock?.type === "situational-dialogue"
          ? (() => {
              const activityItems = normalizeSituationalDialogueActivityItems(current.activityItems);
              const targetItem = activityItems.find((item) => item.id === itemId);
              return targetItem && (isSituationalDialogueIntroductionItem(targetItem) || isSituationalDialogueConclusionItem(targetItem))
                ? activityItems
                : normalizeSituationalDialogueActivityItems(current.activityItems.filter((item) => item.id !== itemId));
            })()
        : selectedBlock?.type === "audio" && current.activityItems.length <= 1
          ? current.activityItems
        : selectedBlock?.type === "tabs" && current.activityItems.length <= TABS_MIN_ITEMS
          ? current.activityItems
        : selectedBlock?.type === "image-grid"
          ? (() => {
              const targetIndex = current.activityItems.findIndex((item) => item.id === itemId);
              if (targetIndex < 0) {
                return current.activityItems;
              }
              return current.activityItems.filter((_, index) => index !== targetIndex);
            })()
        : current.activityItems.filter((item) => item.id !== itemId);

      const next = {
        ...current,
        activityItems: nextActivityItems
      };
      blockFormRef.current = next;
      return next;
    });
  }

  function removeActivityItemImage(itemId: string) {
    const item = blockFormRef.current.activityItems.find((candidate) => candidate.id === itemId);
    if (!item) {
      return;
    }
    updateActivityItem(itemId, {
      assetRefs: (item.assetRefs ?? []).filter((assetRef) => !isSupportedImageAsset(assetRef)),
      mediaFileName: null,
      imageCrop: null,
      imageAccessibility: null,
      imageAnnotationStateRef: null,
      imageAnnotationSourceAssetRef: null
    });
    if (activeActivityItemCropId === itemId) {
      cancelActivityItemCrop();
    }
  }

