  function returnPreviewToChapterMenu() {
    setIsPreviewStarted(false);
    setIsPreviewNavCollapsed(true);
    setPreviewAssistantQuery("");
    setPreviewAssistantResultHtml("");
    setPreviewAssistantOpen(false);
    setPreviewAssistantId("");
    window.setTimeout(() => resetPreviewViewportScroll("auto"), 0);
  }

  function renderPreviewNavigation() {
    const activeChapterId = activeChapter?.id ?? "";
    const chapterIndex = courseProgress.chapters.findIndex((chapter) => chapter.chapterId === activeChapterId);
    const chapterPercent = courseProgress.chapters[chapterIndex]?.percent ?? 0;

    return (
      <aside className={`preview-progress-nav ${isPreviewNavCollapsed ? "collapsed" : ""}`}
        onKeyDown={(event) => {
          if (event.key === "Escape" && !isPreviewNavCollapsed) {
            event.preventDefault();
            setIsPreviewNavCollapsed(true);
            event.currentTarget.querySelector<HTMLButtonElement>(".preview-progress-toggle")?.focus();
          }
        }}>
        <div className="preview-progress-head">
          <button
            aria-label={isPreviewNavCollapsed ? t("preview.showNavigation") : t("preview.hideNavigation")}
            aria-expanded={!isPreviewNavCollapsed}
            aria-describedby="preview-chapter-capsule-label"
            className="preview-progress-toggle"
            onClick={() => setIsPreviewNavCollapsed((current) => !current)}
            type="button"
          >
            <svg aria-hidden="true" viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <path d={isPreviewNavCollapsed ? "M4 6h16M4 12h16M4 18h16" : "M6 6l12 12M18 6L6 18"} />
            </svg>
            <span id="preview-chapter-capsule-label" className="preview-capsule-label">{t("lesson.chapterProgress", { index: Math.max(1, chapterIndex + 1), total: courseProgress.chapters.length })} · {chapterPercent}%</span>
          </button>
          {!isPreviewNavCollapsed ? (
            <button
              aria-label={t("preview.returnToChapterMenu", undefined, "Revenir au menu des chapitres")}
              className="preview-progress-home"
              onClick={returnPreviewToChapterMenu}
              type="button"
            >
              <strong>{project?.title ?? t("lesson.defaultTitle")}</strong>
              <span>{t("preview.percentComplete", { percent: courseProgress.percent })}</span>
              <div className="preview-progress-bar" aria-hidden="true">
                <span style={{ width: `${courseProgress.percent}%` }} />
              </div>
            </button>
          ) : null}
        </div>
        {!isPreviewNavCollapsed ? (
          <nav className="preview-progress-list" aria-label={t("preview.chapterNavigation")}>
            {courseProgress.chapters.map((chapterProgress, index) => {
              const entry = chapterEntries.find((item) => item.chapter.id === chapterProgress.chapterId);
              const isActive = chapterProgress.chapterId === activeChapterId;
              return (
                <button
                  className={isActive ? "active" : ""}
                  disabled={!entry}
                  key={chapterProgress.chapterId}
                  onClick={() => entry && selectPreviewChapter(entry)}
                  type="button"
                >
                  <span className="preview-progress-status" aria-hidden="true">
                    {chapterProgress.percent >= 100 ? "●" : chapterProgress.completed > 0 ? "◔" : "○"}
                  </span>
                  <span>
                    <strong>{chapterProgress.title}</strong>
                    <small>
                      {t("lesson.chapterProgress", { index: index + 1, total: courseProgress.chapters.length })}
                    </small>
                  </span>
                  <span className="preview-progress-percent">{chapterProgress.percent}%</span>
                </button>
              );
            })}
          </nav>
        ) : null}
      </aside>
    );
  }

  function renderPreviewAssistant() {
    if (!isPreviewMode || !isPreviewStarted || !activePreviewAssistant || previewAssistantLockedByQuiz) {
      return null;
    }
    const isPanelOpen = previewAssistantOpen || activePreviewAssistant.alwaysVisible;
    const fallback = activePreviewAssistant.fallbackResponses[0] || "Je ne trouve pas ce terme dans ce glossaire.";
    const assistantAvatarSrc = (() => {
      const avatarRef = activePreviewAssistant.avatarRef?.trim();
      if (!avatarRef) {
        return "";
      }
      if (avatarRef.replace(/\\/g, "/").startsWith("avatars/") && userGlossaryAssistantBankPath) {
        return isTauriRuntimeAvailable()
          ? convertFileSrc(`${userGlossaryAssistantBankPath.replace(/\\/g, "/")}/${avatarRef.replace(/\\/g, "/")}`)
          : "";
      }
      return buildAssetUrl(currentProjectPath, avatarRef);
    })();

    function submitAssistantSearch(event: FormEvent<HTMLFormElement>) {
      event.preventDefault();
      if (!activePreviewAssistant) {
        return;
      }
      const entries = findAssistantEntries(activePreviewAssistant, previewAssistantQuery);
      if (entries.length === 0) {
        setPreviewAssistantResultHtml(`<p>${fallback}</p>`);
        return;
      }
      if (entries.length === 1) {
        setPreviewAssistantResultHtml(entries[0].contentHtml?.trim() || `<p>${fallback}</p>`);
        return;
      }
      setPreviewAssistantResultHtml(
        `<p>${escapeHtml(t("assistant.multipleDefinitions"))}</p><div class="preview-assistant-choice-list">${entries
          .map(
            (entry) =>
              `<button type="button" data-assistant-entry-id="${escapeHtml(entry.id)}">${escapeHtml(entry.term || t("assistant.entryNumber", { count: 1 }))}</button>`
          )
          .join("")}</div>`
      );
    }

    function handleAssistantAnswerClick(event: MouseEvent<HTMLDivElement>) {
      const target = event.target;
      if (!(target instanceof HTMLElement)) {
        return;
      }
      const button = target.closest<HTMLButtonElement>("[data-assistant-entry-id]");
      if (!button || !activePreviewAssistant) {
        return;
      }
      const entry = activePreviewAssistant.entries.find((candidate) => candidate.id === button.dataset.assistantEntryId);
      if (entry) {
        setPreviewAssistantResultHtml(entry.contentHtml?.trim() || `<p>${fallback}</p>`);
      }
    }

    function collapsePreviewAssistant() {
      setPreviewAssistantQuery("");
      setPreviewAssistantResultHtml("");
      setPreviewAssistantOpen(false);
    }

    function resetPreviewAssistant() {
      setPreviewAssistantQuery("");
      setPreviewAssistantResultHtml("");
    }

    return (
      <aside className={`preview-assistant-widget ${activePreviewAssistant.position}`}>
        {isPanelOpen ? (
          <section className="preview-assistant-panel" aria-label={activePreviewAssistant.name}>
            <form className="preview-assistant-search" onSubmit={submitAssistantSearch}>
              {assistantAvatarSrc ? <img alt="" src={assistantAvatarSrc} /> : null}
              <div className="preview-assistant-input-wrap">
                <input
                  onChange={(event) => setPreviewAssistantQuery(event.target.value)}
                  placeholder={t("assistant.searchTerm")}
                  value={previewAssistantQuery}
                />
                <button
                  aria-label={t("common.clearSearch")}
                  className="preview-assistant-reset"
                  onClick={resetPreviewAssistant}
                  type="button"
                >
                  ×
                </button>
              </div>
              {!activePreviewAssistant.alwaysVisible ? (
                <button
                  aria-label={t("assistant.collapse")}
                  className="preview-assistant-collapse"
                  onClick={collapsePreviewAssistant}
                  type="button"
                >
                  <span aria-hidden="true" />
                </button>
              ) : null}
            </form>
            {previewAssistantResultHtml ? (
              <div
                className="preview-assistant-answer rich-content"
                dangerouslySetInnerHTML={{ __html: previewAssistantResultHtml }}
                onClick={handleAssistantAnswerClick}
              />
            ) : null}
          </section>
        ) : null}
        {!activePreviewAssistant.alwaysVisible && !isPanelOpen ? (
          <button
            aria-label={t("assistant.open")}
            className="preview-assistant-toggle"
            onClick={() => setPreviewAssistantOpen((current) => !current)}
            title={t("assistant.keyboardShortcut")}
            type="button"
          >
            ?
          </button>
        ) : null}
      </aside>
    );
  }

  function renderPreviewResponsiveViewport(children: ReactNode) {
    if (!isPreviewResponsiveViewport || !previewDeviceConfig.width || !previewDeviceConfig.height) {
      return children;
    }

    return (
      <PreviewViewport
        chapterMenuActive={!isPreviewStarted}
        height={previewDeviceConfig.height}
        lessonStyle={customLessonFontStyle(currentProjectPath, project, lessonActivitySpacingDraft)}
        width={previewDeviceConfig.width}
      >
        {children}
      </PreviewViewport>
    );
  }

  async function handleUploadSelectedVideoPath(sourcePath: string) {
    if (!selectedBlock || selectedBlock.type !== "media") {
      return;
    }
    const fileName = sourcePath.split(/[\\/]/).pop() || t("activity.media");

    setEditorOriginalMedia((current) =>
      current?.blockId === selectedBlock.id
        ? current
        : {
            blockId: selectedBlock.id,
            assetRefs: [...(selectedBlock.assetRefs ?? [])],
            subtitleRefs: [...(selectedBlock.subtitleRefs ?? [])],
            videoSubtitleOriginalRef: selectedBlock.videoSubtitleOriginalRef ?? null,
            mediaFileName: selectedBlock.mediaFileName ?? "",
            imageCrop: normalizeImageCrop(selectedBlock.imageCrop) ?? null,
            activityItems: selectedBlock.activityItems ?? []
          }
    );
    const reuseAssetRef = await chooseExistingDuplicateAssetFromPath(sourcePath, "video");
    setImportDialog({ status: "running", title: t("media.loadingVideo") });

    try {
      await runAction("upload-media", async () => {
        const nextState = await uploadVideoBlockAssetFromPath(currentProjectPath, selectedBlock.id, sourcePath, reuseAssetRef);
        setPendingBlockMediaDraft({ blockId: selectedBlock.id, mediaFileName: fileName, imageCrop: null });
        setDraftImageCrop(null);
        setIsCropMode(false);
        setWorkspaceState(nextState);
      });
      setImportDialog(null);
    } catch {
      setImportDialog({
        status: "error",
        doneTitle: t("import.loadingInterrupted"),
        message: t("media.videoLoadFailed")
      });
    }
  }

